INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_bdbd40f54a50','bk_ncert_english','9-1-the-fun-they-had','9.1 The Fun They Had',NULL,'public',1,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a6ac7458bea','ch_bdbd40f54a50','text','{"text": "MARGIE even wrote about it that night in her diary. On the page headed 17 May 2157, she wrote, ‘Today Tommy found a real book!’ It was a very old book. Margie’s grandfather once said that when he was a little boy his grandfather told him that there was a time when all stories were printed on paper."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1464b23effe2','ch_bdbd40f54a50','text','{"text": "They turned the pages, which were yellow and crinkly, and it was awfully funny to read words that stood still instead of moving the way they were supposed to — on a screen, you know. And then when they turned back to the page before, it had the same words on it that it had had when they read it the first time."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87f4ed518bba','ch_bdbd40f54a50','text','{"text": "‘Gee,’ said Tommy, ‘what a waste."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a8c3914aff2f','ch_bdbd40f54a50','text','{"text": "When you’re through with the book, you just throw it away, I guess. Our television screen must have had a million books on it and it’s good for plenty more. I wouldn’t throw it away.’"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6dcc5053902c','ch_bdbd40f54a50','text','{"text": "‘Same with mine,’ said Margie."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ef16f37de50','ch_bdbd40f54a50','text','{"text": "She was eleven and hadn’t seen as many telebooks as Tommy had. He was thirteen. She said, ‘Where did you find it?’"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_71a5e756fd6b','ch_bdbd40f54a50','text','{"text": "‘In my house.’"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4cb28a1fa9c9','ch_bdbd40f54a50','text','{"text": "He pointed without looking, because he was busy reading."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07b6efd18044','ch_bdbd40f54a50','text','{"text": "‘In the attic.’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7275762607d8','ch_bdbd40f54a50','text','{"text": "‘What’s it about?’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4a597799dc4c','ch_bdbd40f54a50','text','{"text": "‘School.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bcaa4b172232','ch_bdbd40f54a50','text','{"text": "Margie was scornful."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d9b73855306','ch_bdbd40f54a50','text','{"text": "‘School? What’s there to write about school? I hate school.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_76df4b19196d','ch_bdbd40f54a50','text','{"text": "Margie always hated school, but now she hated it more than ever. The mechanical teacher had been giving her test after test in geography and she had been doing worse and worse until her mother had shaken her head sorrowfully and sent for the County Inspector. He was a round little man with a red face and a whole box of tools with dials and wires. He smiled at Margie and gave her an apple, then took the teacher apart."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f6f879efec8','ch_bdbd40f54a50','text','{"text": "Margie had hoped he wouldn’t know how to put it together again, but he knew how all right, and, after an hour or so, there it was again, large and black and ugly, with a big screen on which all the lessons were shown and the questions were asked. That wasn’t so bad. The part Margie hated most was the slot where she had to put homework and test papers."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1e547bf0eb28','ch_bdbd40f54a50','text','{"text": "She always had to write them out in a punch code they made her learn when she was six years old, and the mechanical teacher calculated the marks in no time. The Inspector had smiled after he was finished and patted Margie’s head. He said to her mother, ‘It’s not the little girl’s fault, Mrs Jones. I think the geography sector was geared a little too quick. Those things happen sometimes. I’ve slowed it up to an average ten-year level."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57d042ba445d','ch_bdbd40f54a50','text','{"text": "Actually, the overall pattern of her progress is quite satisfactory.’"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c27f2783a12a','ch_bdbd40f54a50','text','{"text": "And he patted Margie’s head again. Margie was disappointed. She had been hoping they would take the teacher away altogether. They had once taken Tommy’s teacher away for nearly a month because the history sector had blanked out completely. So she said to Tommy, ‘Why would anyone write about school?’ Tommy looked at her with very superior eyes."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e3fc63d2d6aa','ch_bdbd40f54a50','text','{"text": "‘Because it’s not our kind of school, stupid."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e07cbcaa42ff','ch_bdbd40f54a50','text','{"text": "This is the old kind of school that they had hundreds and hundreds of years ago.’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7099f8be17ef','ch_bdbd40f54a50','text','{"text": "He added loftily, pronouncing the word carefully, ‘Centuries ago.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_419055c37843','ch_bdbd40f54a50','text','{"text": "Margie was hurt."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59ae618624e3','ch_bdbd40f54a50','text','{"text": "‘Well, I don’t know what kind of school they had all that time ago.’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a085e0e59add','ch_bdbd40f54a50','text','{"text": "She read the book over his shoulder for a while, then said, ‘Anyway, they had a teacher.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_854d9cd9e63a','ch_bdbd40f54a50','text','{"text": "‘Sure they had a teacher, but it wasn’t a regular teacher."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2dbba8c719d7','ch_bdbd40f54a50','text','{"text": "It was a man.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c96a8897fc0','ch_bdbd40f54a50','text','{"text": "‘A man? How could a man be a teacher?’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb290f7193ac','ch_bdbd40f54a50','text','{"text": "‘Well, he just told the boys and girls things and gave them homework and asked them questions.’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62882b4be7e5','ch_bdbd40f54a50','text','{"text": "‘A man isn’t smart enough.’"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e4be65df1fc4','ch_bdbd40f54a50','text','{"text": "‘Sure he is. My father knows as much as my teacher.’"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7b7a9d2f1aef','ch_bdbd40f54a50','text','{"text": "‘He knows almost as much, I betcha.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c189664300eb','ch_bdbd40f54a50','text','{"text": "Margie wasn’t prepared to dispute that. She said, ‘I wouldn’t want a strange man in my house to teach me.’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_229a3a66ada0','ch_bdbd40f54a50','text','{"text": "Tommy screamed with laughter."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5151352f4cbc','ch_bdbd40f54a50','text','{"text": "‘You don’t know much, Margie."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18c8dd32ea1a','ch_bdbd40f54a50','text','{"text": "The teachers didn’t live in the house. They had a special building and all the kids went there.’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_417353b007dc','ch_bdbd40f54a50','text','{"text": "‘And all the kids learned the same thing?’"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef6f6eba66cd','ch_bdbd40f54a50','text','{"text": "‘Sure, if they were the same age.’"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b3728902fac','ch_bdbd40f54a50','text','{"text": "‘But my mother says a teacher has to be adjusted to fit the mind of each boy and girl it teaches and that each kid has to be taught differently.’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2444e13bfdf5','ch_bdbd40f54a50','text','{"text": "‘Just the same they didn’t do it that way then."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78e89c58ab10','ch_bdbd40f54a50','text','{"text": "If you don’t like it, you don’t have to read the book.’"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_407c590f2b58','ch_bdbd40f54a50','text','{"text": "‘I didn’t say I didn’t like it,’ Margie said quickly."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2680a9587973','ch_bdbd40f54a50','text','{"text": "She wanted to read about those funny schools. They weren’t even half finished when Margie’s mother called, ‘Margie! School!’ Margie looked up."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5850bf30d45','ch_bdbd40f54a50','text','{"text": "‘Not yet, Mamma.’"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2bf9aec217b3','ch_bdbd40f54a50','text','{"text": "‘Now!’ said Mrs Jones."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3c59b3899e4','ch_bdbd40f54a50','text','{"text": "‘And it’s probably time for Tommy, too.’"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_df6f8dd9df43','ch_bdbd40f54a50','text','{"text": "Margie said to Tommy, ‘Can I read the book some more with you after school?’"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa01515f186c','ch_bdbd40f54a50','text','{"text": "‘May be,’ he said nonchalantly."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b559f3bf3a33','ch_bdbd40f54a50','text','{"text": "He walked away whistling, the dusty old book tucked beneath his arm. Margie went into the schoolroom. It was right next to her bedroom, and the mechanical teacher was on and waiting for her. It was always on at the same time every day except Saturday and Sunday, because her mother said little girls learned better if they learned at regular hours. The screen was lit up, and it said:"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a6ba9aec53a','ch_bdbd40f54a50','text','{"text": "‘Today’s arithmetic lesson is on the addition of proper fractions."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a7b6b1a269c6','ch_bdbd40f54a50','text','{"text": "Please insert yesterday’s homework in the proper slot.’"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4cd98503774e','ch_bdbd40f54a50','text','{"text": "Margie did so with a sigh. She was thinking about the old schools they had when her grandfather’s grandfather was a little boy. All the kids from the whole neighborhood came, laughing and shouting in the schoolyard, sitting together in the schoolroom, going home together at the end of the day. They learned the same things, so they could help one another with the homework and talk about it. And the teachers were people… The mechanical teacher was flashing on the screen:"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c2a35a8c7350','ch_bdbd40f54a50','text','{"text": "‘When we add fractions ½ and ¼...’"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d25f1c7ebda','ch_bdbd40f54a50','text','{"text": "Margie was thinking about how the kids must have loved it in the old days. She was thinking about the fun they had."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac3c60ee23df','ch_bdbd40f54a50','heading','{"level": 2, "text": "Isaac Asimov"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e9c5d905c49','ch_bdbd40f54a50','text','{"text": "*********"}',55);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_3d1a418e048f','bk_ncert_english','9-2-the-road-not-taken','9.2 The Road Not Taken',NULL,'public',2,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_185421cf5091','ch_3d1a418e048f','text','{"text": "Two roads diverged in a yellow wood,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7d4cd2f44b54','ch_3d1a418e048f','text','{"text": "And sorry I could not travel both"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c27dcd187db7','ch_3d1a418e048f','text','{"text": "And be one traveller, long I stood"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2fdc192ac19c','ch_3d1a418e048f','text','{"text": "And looked down one as far as I could"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1207657d5dc9','ch_3d1a418e048f','text','{"text": "To where it bent in the undergrowth;"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61cd069ae263','ch_3d1a418e048f','text','{"text": "Then took the other, just as fair,"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a377e5987ca','ch_3d1a418e048f','text','{"text": "And having perhaps the better claim,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5296c49cc06c','ch_3d1a418e048f','text','{"text": "Because it was grassy and wanted wear;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_68c41902ea19','ch_3d1a418e048f','text','{"text": "Though as for that the passing there"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2296b71cda0a','ch_3d1a418e048f','text','{"text": "Had worn them really about the same."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a02ab1d5c44c','ch_3d1a418e048f','text','{"text": "And both that morning equally lay"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d20aa103a131','ch_3d1a418e048f','text','{"text": "In leaves no step had trodden black."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e7832dddf6c8','ch_3d1a418e048f','text','{"text": "Oh, I kept the first for another day!"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bb1093ae876c','ch_3d1a418e048f','text','{"text": "Yet knowing how way leads on to way,"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_88d342e15742','ch_3d1a418e048f','text','{"text": "I doubted if I should ever come back."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c30a42edfbd','ch_3d1a418e048f','text','{"text": "I shall be telling this with a sigh"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49d1d92984df','ch_3d1a418e048f','text','{"text": "Somewhere ages and ages hence;"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_52705b2e7d55','ch_3d1a418e048f','text','{"text": "Two roads diverged in a wood, and I —"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b680d65ff25','ch_3d1a418e048f','text','{"text": "I took the one less travelled by,"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9433e485359f','ch_3d1a418e048f','text','{"text": "And that has made all the difference."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00635f8e7227','ch_3d1a418e048f','heading','{"level": 2, "text": "Robert Frost"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f555560924e','ch_3d1a418e048f','text','{"text": "*********"}',22);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_00df5be67a8d','bk_ncert_english','9-3-the-sound-of-music','9.3 The Sound of Music',NULL,'public',3,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d5161c447e1','ch_00df5be67a8d','text','{"text": "Part I"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37a025bd1f63','ch_00df5be67a8d','text','{"text": "Evelyn Glennie Listens to Sound without Hearing It"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cfc54e98f74b','ch_00df5be67a8d','text','{"text": "RUSH hour crowds jostle for position on the underground train platform."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c6bbd0bad7fc','ch_00df5be67a8d','text','{"text": "A slight girl, looking younger than her seventeen years, was nervous yet excited as she felt the vibrations of the approaching train. It was her first day at the prestigious Royal Academy of Music in London and daunting enough for any teenager fresh from a Scottish farm. But this aspiring musician faced a bigger challenge than most: she was profoundly deaf. Evelyn Glennie’s loss of hearing had been gradual."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2a1cf24a377','ch_00df5be67a8d','text','{"text": "Her mother remembers noticing something was wrong when the eight-year-old Evelyn was waiting to play the piano."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca494db07202','ch_00df5be67a8d','text','{"text": "‘They called her name and she didn’t move."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_315bd53fe380','ch_00df5be67a8d','text','{"text": "I suddenly realised she hadn’t heard,’ says Isabel Glennie. For quite a while Evelyn managed to conceal her growing deafness from friends and teachers. But by the time she was eleven her marks had deteriorated and her headmistress urged her parents to take her to a specialist. It was then discovered that her hearing was severely impaired as a result of gradual nerve damage. They were advised that she should be fitted with hearing aids and sent to a school for the deaf."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_628a5f6d3ad6','ch_00df5be67a8d','text','{"text": "‘Everything suddenly looked black,’ says Evelyn."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_185ce526b3a4','ch_00df5be67a8d','text','{"text": "But Evelyn was not going to give up. She was determined to lead a normal life and pursue her interest in music. One day she noticed a girl playing a xylophone and decided that she wanted to play it too. Most of the teachers discouraged her but percussionist Ron Forbes spotted her potential. He began by tuning two large drums to different notes."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca9bac859107','ch_00df5be67a8d','text','{"text": "‘Don’t listen through your ears,’ he would say, ‘try to sense it some other way.’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_afed4502099e','ch_00df5be67a8d','text','{"text": "Says Evelyn, ‘Suddenly I realised I could feel the higher drum from the waist up and the lower one from the waist down.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72e25be6e93e','ch_00df5be67a8d','text','{"text": "Forbes repeated the exercise, and soon Evelyn discovered that she could sense certain notes in different parts of her body."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a7b02516f356','ch_00df5be67a8d','text','{"text": "‘I had learnt to open my mind and body to sounds and vibrations.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35a283c1d01d','ch_00df5be67a8d','text','{"text": "The rest was sheer determination and hard work. She never looked back from that point onwards. She toured the United Kingdom with a youth orchestra and by the time she was sixteen, she had decided to make music her life. She auditioned for the Royal Academy of Music and scored one of the highest marks in the history of the academy. She gradually moved from orchestral work to solo performances. At the end of her three-year course, she had captured most of the top awards."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6661493dcb76','ch_00df5be67a8d','text','{"text": "And for all this, Evelyn won’t accept any hint of heroic achievement."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_12fe01aa9bca','ch_00df5be67a8d','text','{"text": "‘If you work hard and know where you are going, you’ll get there.’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5114814db8fd','ch_00df5be67a8d','text','{"text": "And she got right to the top, the world’s most sought-after multipercussionist with a mastery of some thousand instruments, and hectic international schedule. It is intriguing to watch Evelyn function so effortlessly without hearing. In our two-hour discussion she never missed a word."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a52946a96ff','ch_00df5be67a8d','text','{"text": "‘Men with bushy beards give me trouble,’ she laughed."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_783333f16299','ch_00df5be67a8d','text','{"text": "‘It is not just watching the lips, it’s the whole face, especially the eyes.’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9e52a00e001','ch_00df5be67a8d','text','{"text": "She speaks flawlessly with a Scottish lilt."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_35836898ba1c','ch_00df5be67a8d','text','{"text": "‘My speech is clear because I could hear till I was eleven,’ she says."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ba0d05582690','ch_00df5be67a8d','text','{"text": "But that doesn’t explain how she managed to learn French and master basic Japanese. As for music, she explains, ‘It pours in through every part of my body. It tingles in the skin, my cheekbones and even in my hair.’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d88b534ed67e','ch_00df5be67a8d','text','{"text": "When she plays the xylophone, she can sense the sound passing up the stick into her fingertips. By leaning against the drums, she can feel the resonances flowing into her body. On a wooden platform she removes her shoes so that the vibrations pass through her bare feet and up her legs. Not surprisingly, Evelyn delights her audiences. In 1991 she was presented with the Royal Philharmonic Society’s prestigious Soloist of the Year Award."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_961082b1ae81','ch_00df5be67a8d','text','{"text": "Says master percussionist James Blades, ‘God may have taken her hearing but he has given her back something extraordinary. What we hear, she feels — far more deeply than any of us. That is why she expresses music so beautifully.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63a87aac2e04','ch_00df5be67a8d','text','{"text": "Evelyn confesses that she is something of a workaholic."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_04693d106d42','ch_00df5be67a8d','text','{"text": "‘I’ve just got to work ... often harder than classical musicians. But the rewards are enormous.’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_50fa794455c7','ch_00df5be67a8d','text','{"text": "Apart from the regular concerts, Evelyn also gives free concerts in prisons and hospitals. She also gives high priority to classes for young musicians. Ann Richlin of the Beethoven Fund for Deaf Children says, ‘She is a shining inspiration for deaf children. They see that there is nowhere that they cannot go.’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d362d23bf0d','ch_00df5be67a8d','text','{"text": "Evelyn Glennie has already accomplished more than most people twice her age. She has brought percussion to the front of the orchestra, and demonstrated that it can be very moving. She has given inspiration to those who are handicapped, people who look to her and say, ‘If she can do it, I can.’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c491ee1c7fbd','ch_00df5be67a8d','text','{"text": "And, not the least, she has given enormous pleasure to millions."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fdbeb08ae8e','ch_00df5be67a8d','heading','{"level": 2, "text": "Deborah Cowley"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c35787330192','ch_00df5be67a8d','text','{"text": "Part II"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_864b199ea526','ch_00df5be67a8d','text','{"text": "The Shehnai of Bismillah Khan"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17b8b631f9be','ch_00df5be67a8d','text','{"text": "EMPEROR Aurangzeb banned the playing of a musical instrument called pungi in the royal residence for it had a shrill unpleasant sound. Pungi became the generic name for reeded noisemakers. Few had thought that it would one day be revived. A barber of a family of professional musicians, who had access to the royal palace, decided to improve the tonal quality of the pungi."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67ba4e5e3315','ch_00df5be67a8d','text','{"text": "He chose a pipe with a natural hollow stem that was longer and broader than the pungi, and made seven holes on the body of the pipe. When he played on it, closing and opening some of these holes, soft and melodious sounds were produced. He played the instrument before royalty and everyone was impressed. The instrument so different from the pungi had to be given a new name."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a44349e9bcf8','ch_00df5be67a8d','text','{"text": "As the story goes, since it was first played in the Shah’s chambers and was played by a nai (barber), the instrument was named the"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_540991ac01d0','ch_00df5be67a8d','text','{"text": "‘shehnai’. The sound of the shehnai began to be considered auspicious. And for this reason it is still played in temples and is an indispensable component of any North Indian wedding. In the past, the shehnai was part of the naubat or traditional ensemble of nine instruments found at royal courts. Till recently it was used only in temples and weddings. The credit for bringing this instrument onto the classical stage goes to Ustad Bismillah Khan."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5248951fb182','ch_00df5be67a8d','text','{"text": "As a five-year old, Bismillah Khan played gillidanda near a pond in the ancient estate of Dumraon in Bihar. He would regularly go to the nearby Bihariji temple to sing the Bhojpuri"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9a4aa5760061','ch_00df5be67a8d','text','{"text": "‘Chaita’, at the end of which he would earn a big laddu weighing 1.25 kg, a prize given by the local Maharaja. This happened 80 years ago, and the little boy has travelled far to earn the highest civilian award in India — the Bharat Ratna. Born on 21 March 1916, Bismillah belongs to a well-known family of musicians from Bihar. His grandfather, Rasool Bux Khan, was the shehnainawaz of the Bhojpur king’s court."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0afa5e0f3709','ch_00df5be67a8d','text','{"text": "His father, Paigambar Bux, and other paternal ancestors were also great shehnai players. The young boy took to music early in life. At the age of three when his mother took him to his maternal uncle’s house in Benaras (now Varanasi), Bismillah was fascinated watching his uncles practise the shehnai. Soon Bismillah started accompanying his uncle, Ali Bux, to the Vishnu temple of Benaras where Bux was employed to play the shehnai."}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1be0cc42c0d','ch_00df5be67a8d','text','{"text": "Ali Bux would play the shehnai and Bismillah would sit captivated for hours on end. Slowly, he started getting lessons in playing the instrument and would sit practising throughout the day. For years to come the temple of Balaji and Mangala Maiya and the banks of the Ganga became the young apprentice’s favourite haunts where he could practise in solitude."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7f1b1e45d63','ch_00df5be67a8d','text','{"text": "The flowing waters of the Ganga inspired him to improvise and invent raagas that were earlier considered to be beyond the range of the shehnai. At the age of 14, Bismillah accompanied his uncle to the Allahabad Music Conference. At the end of his recital, Ustad Faiyaz Khan patted the young boy’s back and said, ‘Work hard and you shall make it.’"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f679992815f','ch_00df5be67a8d','text','{"text": "With the opening of the All India Radio in Lucknow in 1938 came Bismillah’s big break. He soon became an often-heard shehnai player on radio. When India gained independence on 15 August 1947, Bismillah Khan became the first Indian to greet the nation with his shehnai. He poured his heart out into Raag Kafi from the Red Fort to an audience which included Pandit Jawaharlal Nehru, who later gave his famous"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_460953695357','ch_00df5be67a8d','text','{"text": "‘Tryst with Destiny’ speech."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aaebf62290e8','ch_00df5be67a8d','text','{"text": "Bismillah Khan has given many memorable performances both in India and abroad. His first trip abroad was to Afghanistan where King Zahir Shah was so taken in by the maestro that he gifted him priceless Persian carpets and other souvenirs. The King of Afghanistan was not the only one to be fascinated with Bismillah’s music. Film director Vijay Bhatt was so impressed after hearing Bismillah play at a festival that he named a film after the instrument called Gunj Uthi Shehnai."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_783dce41777a','ch_00df5be67a8d','text','{"text": "The film was a hit, and one of Bismillah Khan’s compositions, ‘Dil ka khilona hai toot gaya ...,’ turned out to be a nationwide chartbuster! Despite this huge success in the celluloid world, Bismillah Khan’s ventures in film music were limited to two: Vijay Bhatt’s Gunj Uthi Shehnai and Vikram Srinivas’s Kannada venture, Sanadhi Apanna."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61dd486264ad','ch_00df5be67a8d','text','{"text": "‘I just can’t come to terms with the artificiality and glamour of the film world,’ he says with emphasis."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f46eb3d1aa6d','ch_00df5be67a8d','text','{"text": "Awards and recognition came thick and fast. Bismillah Khan became the first Indian to be invited to perform at the prestigious Lincoln Centre Hall in the United States of America. He also took part in the World Exposition in Montreal, in the Cannes Art Festival and in the Osaka Trade Fair. So well known did he become internationally that an auditorium in Teheran was named after him — Tahar Mosiquee Ustaad Bismillah Khan."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fbd3eb9e64b3','ch_00df5be67a8d','text','{"text": "National awards like the Padmashri, the Padma Bhushan and the Padma Vibhushan were conferred on him. In 2001, Ustad Bismillah Khan was awarded India’s highest civilian award, the Bharat Ratna. With the coveted award resting on his chest and his eyes glinting with rare happiness he said, ‘All I would like to say is: Teach your children music, this is Hindustan’s richest tradition;"}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_591faa03d93f','ch_00df5be67a8d','text','{"text": "even the West is now coming to learn our music.’"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c32195780bce','ch_00df5be67a8d','text','{"text": "’ In spite of having travelled all over the world — Khansaab as he is fondly called — is exceedingly fond of Benaras and Dumraon and they remain for him the most wonderful towns of the world. A student of his once wanted him to head a shehnai school in the U.S.A., and the student promised to recreate the atmosphere of Benaras by replicating the temples there. But Khansaab asked him if he would be able to transport River Ganga as well."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e46d27ee2f1','ch_00df5be67a8d','text','{"text": "Later he is remembered to have said, ‘That is why whenever I am in a foreign country, I keep yearning to see Hindustan. While in Mumbai, I think of only Benaras and the holy Ganga. And while in Benaras, I miss the unique mattha of Dumraon.’"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_161c30e5be54','ch_00df5be67a8d','text','{"text": "Ustad Bismillah Khan’s life is a perfect example of the rich, cultural heritage of India, one that effortlessly accepts that a devout Muslim like him can very naturally play the shehnai every morning at the Kashi Vishwanath temple. [Ustad Bismillah Khan passed away on 21 August 2006 at the age of ninety after a prolonged illness. He was given a state funeral and the Government of India declared one day of national mourning.]"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cc150855be1','ch_00df5be67a8d','text','{"text": "Padma Bhushan Kishori Amonkar:"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0fb9555f98cd','ch_00df5be67a8d','text','{"text": "Padma Bhushan Kishori Amonkar, widely considered the finest female vocalist of her generation, was born in 1931, daughter of another great artist, Smt. Mogubai Kurdikar. In her early years she absorbed the approach and repertoire of her distinguished mother’s teacher Ustad Alladiya Khan. As her own style developed, however, she moved away from Alladiya Khan’s ‘Jaipur- Atrauli gharana’ style in some respects, and as a mature artist her approach is usually regarded as an individual, if not unique, variant of the Jaipur model. Kishori Amonkar is a thinker, besotted by what she calls the mysterious world of her raagas. She dissects them with the precision of a perfectionist, almost like a scientist, until the most subtle of shades and emotions emerge and re-emerge. She is very much inspired by the teachings of the ancient Vedic sages, written at a time when vocal music was highly devotional in character. This soul searching quality of her music, coupled with a very intellectual approach to raaga performance has gained her quite a following in India and has helped to revive the study of khayal. Significant awards bestowed on this artist include the Sangeet Natak Akademi Award (1985), the Padma Bhushan (1987), and the highly coveted Sangeet Samradhini Award (considered one of the most prestigious awards in Indian Classical Music) in 1997."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58bb7e511e47','ch_00df5be67a8d','text','{"text": "*********"}',55);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_5b63cae4296f','bk_ncert_english','9-4-wind','9.4 Wind',NULL,'public',4,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f13a83471280','ch_5b63cae4296f','text','{"text": "Wind, come softly."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7b1fcef7e11','ch_5b63cae4296f','text','{"text": "Don’t break the shutters of the windows."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c91acc9d5022','ch_5b63cae4296f','text','{"text": "Don’t scatter the papers."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3121c415cff','ch_5b63cae4296f','text','{"text": "Don’t throw down the books on the shelf."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_505f20d95ba4','ch_5b63cae4296f','text','{"text": "There, look what you did — you threw them all down."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb4cc5b332f6','ch_5b63cae4296f','text','{"text": "You tore the pages of the books."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22bfb87d5140','ch_5b63cae4296f','text','{"text": "You brought rain again."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cecd663196e8','ch_5b63cae4296f','text','{"text": "You’re very clever at poking fun at weaklings."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72ebf114ee57','ch_5b63cae4296f','text','{"text": "Frail crumbling houses, crumbling doors, crumbling rafters,"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b64cd0191c2','ch_5b63cae4296f','text','{"text": "crumbling wood, crumbling bodies, crumbling lives,"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9657be027532','ch_5b63cae4296f','text','{"text": "crumbling hearts —"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b0368b1c093','ch_5b63cae4296f','text','{"text": "the wind god winnows and crushes them all."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5b1ed02f1a3','ch_5b63cae4296f','text','{"text": "He won’t do what you tell him."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_51d41bdd65e5','ch_5b63cae4296f','text','{"text": "So, come, let’s build strong homes,"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99c2b6d86f04','ch_5b63cae4296f','text','{"text": "Let’s joint the doors firmly."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0dfe80181cc2','ch_5b63cae4296f','text','{"text": "Practise to firm the body."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e0ac3f7e1fa','ch_5b63cae4296f','text','{"text": "Make the heart steadfast."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_767966b4e706','ch_5b63cae4296f','text','{"text": "Do this, and the wind will be friends with us."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_02952be277d0','ch_5b63cae4296f','text','{"text": "The wind blows out weak fires."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22e0ab1c55a2','ch_5b63cae4296f','text','{"text": "He makes strong fires roar and flourish."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_af66076091ca','ch_5b63cae4296f','text','{"text": "His friendship is good."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a6ec1439360a','ch_5b63cae4296f','text','{"text": "We praise him every day."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_49c1b0b48104','ch_5b63cae4296f','heading','{"level": 2, "text": "Subramania Bharati"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_752645b1f91d','ch_5b63cae4296f','text','{"text": "*********"}',24);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_cba0c22af971','bk_ncert_english','9-5-the-little-girl','9.5 The Little Girl',NULL,'public',5,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6bdf83a748dc','ch_cba0c22af971','text','{"text": "TO the little girl he was a figure to be feared and avoided."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e58fd82e54ce','ch_cba0c22af971','text','{"text": "Every morning before going to work he came into her room and gave her a casual kiss, to which she responded with"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2a138ab74602','ch_cba0c22af971','text','{"text": "‘Goodbye, Father’."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e71edb986fa6','ch_cba0c22af971','text','{"text": "And oh, there was a glad sense of relief when she heard the noise of the carriage growing fainter and fainter down the long road! In the evening when he came home she stood near the staircase and heard his loud voice in the hall."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ddfbe9df0cbf','ch_cba0c22af971','text','{"text": "‘Bring my tea into the drawing-room... Hasn’t the paper come yet? Mother, go and see if my paper’s out there — and bring me my slippers.’"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8e7da799b2c6','ch_cba0c22af971','text','{"text": "‘Kezia,’ Mother would call to her, ‘if you’re a good girl you can come down and take off father’s boots.’"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c574a913586','ch_cba0c22af971','text','{"text": "Slowly the girl would slip down the stairs, more slowly still across the hall, and push open the drawing-room door. By that time he had his spectacles on and looked at her over them in a way that was terrifying to the little girl."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ac9cd9b5ff77','ch_cba0c22af971','text','{"text": "‘Well, Kezia, hurry up and pull off these boots and take them outside. Have you been a good girl today?’"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d1630563ff0','ch_cba0c22af971','text','{"text": "‘I d-d-don’t know, Father.’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e994aed701f1','ch_cba0c22af971','text','{"text": "‘You d-d-don’t know? If you stutter like that Mother will have to take you to the doctor.’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4818fb81c6f','ch_cba0c22af971','text','{"text": "She never stuttered with other people — had quite given it up — but only with Father, because then she was trying so hard to say the words properly."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_425b79c222a3','ch_cba0c22af971','text','{"text": "‘What’s the matter? What are you looking so wretched about? Mother, I wish you taught this child not to appear on the brink of suicide... Here, Kezia, carry my teacup back to the table carefully.’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea4c0f5f9128','ch_cba0c22af971','text','{"text": "He was so big — his hands and his neck, especially his mouth when he yawned. Thinking about him alone was like thinking about a giant. On Sunday afternoons Grandmother sent her down to the drawing-room to have a"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d57c61c1c506','ch_cba0c22af971','text','{"text": "‘nice talk with Father and Mother’."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b7bf2244275','ch_cba0c22af971','text','{"text": "But the little girl always found Mother reading and Father stretched out on the sofa, his handkerchief on his face, his feet on one of the best cushions, sleeping soundly and snoring. She sat on a stool, gravely watched him until he woke and stretched, and asked the time — then looked at her."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9e50a488c0a4','ch_cba0c22af971','text','{"text": "‘Don’t stare so, Kezia. You look like a little brown owl.’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ea69f3d7074','ch_cba0c22af971','text','{"text": "One day, when she was kept indoors with a cold, her grandmother told her that father’s birthday was next week, and suggested she should make him a pin-cushion for a gift out of a beautiful piece of yellow silk. Laboriously, with a double cotton, the little girl stitched three sides. But what to fill it with? That was the question. The grandmother was out in the garden, and she wandered into Mother’s bedroom to look for scraps."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d194ae27fa67','ch_cba0c22af971','text','{"text": "On the bed-table she discovered a great many sheets of fine paper, gathered them up, tore them into tiny pieces, and stuffed her case, then sewed up the fourth side. That night there was a hue and cry in the house. Father’s great speech for the Port Authority had been lost. Rooms were searched;"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6a36b06c1e81','ch_cba0c22af971','text','{"text": "servants questioned. Finally Mother came into Kezia’s room."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97e415669c06','ch_cba0c22af971','text','{"text": "‘Kezia, I suppose you didn’t see some papers on a table in our room?’"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_010408bfcdba','ch_cba0c22af971','text','{"text": "‘Oh yes,’ she said, ‘I tore them up for my surprise.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_508c227da733','ch_cba0c22af971','text','{"text": "‘What!’ screamed Mother."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0843dc21fd9b','ch_cba0c22af971','text','{"text": "‘Come straight down to the dining-room this instant.’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1cd14e2e9075','ch_cba0c22af971','text','{"text": "And she was dragged down to where Father was pacing to and fro, hands behind his back."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c29701ee4837','ch_cba0c22af971','text','{"text": "‘Well?’ he said sharply. Mother explained. He stopped and stared at the child."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_817b719c0d1c','ch_cba0c22af971','text','{"text": "‘Did you do that?’"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b9602772a90','ch_cba0c22af971','text','{"text": "‘N-n-no’, she whispered."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcfd4cacf810','ch_cba0c22af971','text','{"text": "‘Mother, go up to her room and fetch down the damned thing — see that the child’s put to bed this instant.’"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6e2856460ebd','ch_cba0c22af971','text','{"text": "Crying too much to explain, she lay in the shadowed room watching the evening light make a sad little pattern on the floor. Then Father came into the room with a ruler in his hands."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fb6f97f12227','ch_cba0c22af971','text','{"text": "‘I am going to beat you for this,’ he said."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd45a21abad9','ch_cba0c22af971','text','{"text": "‘Oh, no, no’, she screamed, hiding under the bedclothes."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bca97f31a8d6','ch_cba0c22af971','text','{"text": "He pulled them aside."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6240dd17c670','ch_cba0c22af971','text','{"text": "‘Sit up,’ he ordered, ‘and hold out your hands."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c6fe32a9748','ch_cba0c22af971','text','{"text": "You must be taught once and for all not to touch what does not belong to you.’"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_062823e998de','ch_cba0c22af971','text','{"text": "‘But it was for your b-b-birthday.’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2505c96337f2','ch_cba0c22af971','text','{"text": "Down came the ruler on her little, pink palms. 8. Hours later, when Grandmother had wrapped her in a shawl and rocked her in the rocking-chair, the child clung to her soft body."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2ac97e94f11d','ch_cba0c22af971','text','{"text": "‘What did God make fathers for?’ she sobbed."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1aadaa22c94e','ch_cba0c22af971','text','{"text": "‘Here’s a clean hanky, darling. Blow your nose. Go to sleep, pet;"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25f31b564b36','ch_cba0c22af971','text','{"text": "you’ll forget all about it in the morning. I tried to explain to Father but he was too upset to listen tonight.’"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2cbd9ef29299','ch_cba0c22af971','text','{"text": "But the child never forgot. Next time she saw him she quickly put both hands behind her back and a red colour flew into her cheeks. The Macdonalds lived next door. They had five children. Looking through a gap in the fence the little girl saw them playing"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c0610856ccb','ch_cba0c22af971','text','{"text": "‘tag’ in the evening. The father with the baby, Mao, on his shoulders, two little girls hanging on to his coat pockets ran round and round the flower-beds, shaking with laughter. Once she saw the boys turn the hose on him—and he tried to catch them laughing all the time. Then it was she decided there were different sorts of fathers. Suddenly, one day, Mother became ill, and she and Grandmother went to hospital. The little girl was left alone in the house with Alice, the cook."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ca6ec4eecffe','ch_cba0c22af971','text','{"text": "That was all right in the daytime, but while Alice was putting her to bed she grew suddenly afraid."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_64698d43c9a9','ch_cba0c22af971','text','{"text": "‘What’ll I do if I have a nightmare?’ she asked."}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0140490794d7','ch_cba0c22af971','text','{"text": "‘I often have nightmares and then Grannie takes me into her bed—I can’t stay in the dark—it all gets"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6f4ae03bf495','ch_cba0c22af971','text','{"text": "‘whispery’…’"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fc16933cfcb','ch_cba0c22af971','text','{"text": "‘You just go to sleep, child,’ said Alice, pulling off her socks, ‘and don’t you scream and wake your poor Pa.’"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0eb8c1b3163f','ch_cba0c22af971','text','{"text": "But the same old nightmare came — the butcher with a knife and a rope, who came nearer and nearer, smiling that dreadful smile, while she could not move, could only stand still, crying out, ‘Grandma! Grandma!’ She woke shivering to see Father beside her bed, a candle in his hand."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3442909eb8e7','ch_cba0c22af971','text','{"text": "‘What’s the matter?’ he said. 11."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06d2b7cd5ad9','ch_cba0c22af971','text','{"text": "‘Oh, a butcher — a knife — I want Grannie.’"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c52790a11c8','ch_cba0c22af971','text','{"text": "He blew out the candle, bent down and caught up the child in his arms, carrying her along the passage to the big bedroom. A newspaper was on the bed. He put away the paper, then carefully tucked up the child. He lay down beside her. Half asleep still, still with the butcher’s smile all about her it seemed, she crept close to him, snuggled her head under his arm, held tightly to his shirt. Then the dark did not matter;"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f96178bdbf40','ch_cba0c22af971','text','{"text": "she lay still."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a386ea2fbcf7','ch_cba0c22af971','text','{"text": "‘Here, rub your feet against my legs and get them warm,’ said Father."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbd0b6685a08','ch_cba0c22af971','text','{"text": "Tired out, he slept before the little girl. A funny feeling came over her. Poor Father, not so big, after all — and with no one to look after him. He was harder than Grandmother, but it was a nice hardness. And every day he had to work and was too tired to be a Mr Macdonald… She had torn up all his beautiful writing… She stirred suddenly, and sighed."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b471899ccf4b','ch_cba0c22af971','text','{"text": "‘What’s the matter?’ asked her father."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27b6f20ddfaf','ch_cba0c22af971','text','{"text": "‘Another dream?’"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78174d533023','ch_cba0c22af971','text','{"text": "‘Oh,’ said the little girl, ‘my head’s on your heart. I can hear it going. What a big heart you’ve got, Father dear.’"}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32d5a2669204','ch_cba0c22af971','heading','{"level": 2, "text": "Katherine Mansfield"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf40962ef8d6','ch_cba0c22af971','text','{"text": "*********"}',58);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_357019e51bbc','bk_ncert_english','9-6-a-truly-beautiful-mind','9.6 A Truly Beautiful Mind',NULL,'public',6,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_435352fd15d5','ch_357019e51bbc','text','{"text": "ALBERT Einstein was born on 14 March 1879 in the German city of Ulm, without any indication that he was destined for greatness. On the contrary, his mother thought Albert was a freak. To her, his head seemed much too large. At the age of two-and-a-half, Einstein still wasn’t talking. When he finally did learn to speak, he uttered everything twice."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcdbe16471c4','ch_357019e51bbc','text','{"text": "Einstein did not know what to do with other children, and his playmates called him"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8b11d60f171','ch_357019e51bbc','text','{"text": "‘Brother Boring.’"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_921ad017bb4c','ch_357019e51bbc','text','{"text": "So the youngster played by himself much of the time. He especially loved mechanical toys. Looking at his newborn sister, Maja, he is said to have said:"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc287df7de59','ch_357019e51bbc','text','{"text": "‘Fine, but where are her wheels?’ A headmaster once told his father that what Einstein chose as a profession wouldn’t matter, because"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2159c12314e7','ch_357019e51bbc','text','{"text": "‘he’ll never make a success at anything.’"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7a71ae1496f','ch_357019e51bbc','text','{"text": "Einstein began learning to play the violin at the age of six, because his mother wanted him to;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5bc577785e5f','ch_357019e51bbc','text','{"text": "he later became a gifted amateur violinist, maintaining this skill throughout his life. But Albert Einstein was not a bad pupil. He went to high school in Munich, where Einstein’s family had moved when he was 15 months old, and scored good marks in almost every subject. Einstein hated the school’s regimentation, and often clashed with his teachers."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b07a8353fab2','ch_357019e51bbc','text','{"text": "At the age of 15, Einstein felt so stifled there that he left the school for good. The previous year, Albert’s parents had moved to Milan, and left their son with relatives. After prolonged discussion, Einstein got his wish to continue his education in German-speaking Switzerland, in a city which was more liberal than Munich. Einstein was highly gifted in mathematics and interested in physics, and after finishing school, he decided to study at a university in Zurich."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_900e8cfa33f9','ch_357019e51bbc','text','{"text": "But science wasn’t the only thing that appealed to the dashing young man with the walrus moustache. He also felt a special interest in a fellow student, Mileva Maric, whom he found to be a ‘clever creature.’"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1b4f6abb50b','ch_357019e51bbc','text','{"text": "This young Serb had come to Switzerland because the University in Zurich was one of the few in Europe where women could get degrees. Einstein saw in her an ally against the ‘philistines’— those people in his family and at the university with whom he was constantly at odds. The couple fell in love. Letters survive in which they put their affection into words, mixing science with tenderness. Wrote Einstein:"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_706e1f9348c8','ch_357019e51bbc','text','{"text": "‘How happy and proud I shall be when we both have brought our work on relativity to a victorious conclusion.’"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da2c444136ae','ch_357019e51bbc','text','{"text": "In 1900, at the age of 21, Albert Einstein was a university graduate and unemployed. He worked as a teaching assistant, gave private lessons and finally secured a job in 1902 as a technical expert in the patent office in Bern. While he was supposed to be assessing other people’s inventions, Einstein was actually developing his own ideas in secret. He is said to have jokingly called his desk drawer at work the ‘bureau of theoretical physics.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f43d408ee4a3','ch_357019e51bbc','text','{"text": "One of the famous papers of 1905 was Einstein’s Special Theory of Relativity, according to which time and distance are not absolute. Indeed, two perfectly accurate clocks will not continue to show the same time if they come together again after a journey if one of them has been moving very fast relative to the other."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1faf98b08f5','ch_357019e51bbc','text','{"text": "From this followed the world’s most famous formula which describes the relationship between mass and energy:"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aecc82a4fd64','ch_357019e51bbc','text','{"text": "E = mc2"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_54cb582e4f45','ch_357019e51bbc','text','{"text": "In this mathematical equation, E stands for energy, m for mass and c for the speed of the light in a vacuum (about 300,000 km/s). While Einstein was solving the most difficult problems in physics, his private life was unravelling. Albert had wanted to marry Mileva right after finishing his studies, but his mother was against it."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_99217442c3e5','ch_357019e51bbc','text','{"text": "She thought Mileva, who was three years older than her son, was too old for him. She was also bothered by Mileva’s intelligence."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b7a3d754ea85','ch_357019e51bbc','text','{"text": "‘She is a book like you,’ his mother said."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b87a00a237c','ch_357019e51bbc','text','{"text": "Einstein put the wedding off. The pair finally married in January 1903, and had two sons. But a few years later, the marriage faltered. Mileva, meanwhile, was losing her intellectual ambition and becoming an unhappy housewife. After years of constant fighting, the couple finally divorced in 1919. Einstein married his cousin Elsa the same year. Einstein’s new personal chapter coincided with his rise to world fame."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c0f4772eca09','ch_357019e51bbc','text','{"text": "In 1915, he had published his General Theory of Relativity, which provided a new interpretation of gravity. An eclipse of the sun in 1919 brought proof that it was accurate. Einstein had correctly calculated in advance the extent to which the light from fixed stars would be deflected through the sun’s gravitational field. The newspapers proclaimed his work as ‘a scientific revolution.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef7ae6588ca2','ch_357019e51bbc','text','{"text": "Einstein received the Nobel Prize for Physics in 1921. He was showered with honours and invitations from all over the world, and lauded by the press. When the Nazis came to power in Germany in 1933, Einstein emigrated to the United States. Five years later, the discovery of nuclear fission in Berlin had American physicists in an uproar. Many of them had fled from Fascism, just as Einstein had, and now they were afraid the Nazis could build and use an atomic bomb."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ddbd1aa8aacb','ch_357019e51bbc','text','{"text": "At the urging of a colleague, Einstein wrote a letter to the American President, Franklin D. Roosevelt, on 2 August 1939, in which he warned:"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_300f5d0a3f7d','ch_357019e51bbc','text','{"text": "‘A single bomb of this type . . . exploded in a port, might very well destroy the whole port together with some of the surrounding territory.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_69930fae4d2f','ch_357019e51bbc','text','{"text": "His words did not fail to have an effect. The Americans developed the atomic bomb in a secret project of their own, and dropped it on the Japanese cities of Hiroshima and Nagasaki in August 1945. Einstein was deeply shaken by the extent of the destruction. This time he wrote a public missive to the United Nations. In it he proposed the formation of a world government. Unlike the letter to Roosevelt, this one made no impact."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb0899e0e46a','ch_357019e51bbc','text','{"text": "But over the next decade, Einstein got ever more involved in politics — agitating for an end to the arms buildup and using his popularity to campaign for peace and democracy. 17. When Einstein died in 1955 at the age of 76, he was celebrated as a visionary and world citizen as much as a scientific genius."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0c689a9c060','ch_357019e51bbc','text','{"text": "*********"}',27);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_f0e90cfd2ada','bk_ncert_english','9-7-the-lake-isle-of-innisfree','9.7 The Lake Isle of Innisfree',NULL,'public',7,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62e2cf15fdec','ch_f0e90cfd2ada','text','{"text": "I will arise and go now, and go to Innisfree,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f9a2e9f2e67','ch_f0e90cfd2ada','text','{"text": "And a small cabin build there, of clay and wattles made:"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_862ad75ff8c9','ch_f0e90cfd2ada','text','{"text": "Nine bean-rows will I have there, a hive for the honeybee,"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7e5ad47a18a','ch_f0e90cfd2ada','text','{"text": "And live alone in the bee-loud glade."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8924c5785637','ch_f0e90cfd2ada','text','{"text": "And I shall have some peace there, for peace comes dropping slow"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7a0d2a7501c','ch_f0e90cfd2ada','text','{"text": "Dropping from the veils of the morning to where the cricket sings;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_883bed9e7db1','ch_f0e90cfd2ada','text','{"text": "There midnight’s all a glimmer, and noon a purple glow,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a203a99fbe96','ch_f0e90cfd2ada','text','{"text": "And evenings full of the linnet’s wings."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_220c6e1e3692','ch_f0e90cfd2ada','text','{"text": "I will arise and go now, for always night and day"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a7a922e40c9','ch_f0e90cfd2ada','text','{"text": "I hear the lake water lapping with low sounds by the shore;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5587b4ed2b48','ch_f0e90cfd2ada','text','{"text": "While I stand on the roadway, or on the pavements grey,"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b3fa45e8af28','ch_f0e90cfd2ada','text','{"text": "I hear it in the deep heart’s core."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcc13399e2f3','ch_f0e90cfd2ada','heading','{"level": 2, "text": "William Butler Yeats"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cde1897b2b97','ch_f0e90cfd2ada','text','{"text": "*********"}',14);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_ea65f5bf88df','bk_ncert_english','9-8-the-snake-and-the-mirror','9.8 The Snake and the Mirror',NULL,'public',8,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_be98ea6edcb8','ch_ea65f5bf88df','text','{"text": "‘HAS a snake ever coiled itself round any part of your body? A full-blooded cobra?’ All of us fell silent."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5ead0ad4adb','ch_ea65f5bf88df','text','{"text": "The question came from the homeopath. The topic came up when we were discussing snakes. We listened attentively as the doctor continued with his tale. It was a hot summer night;"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f74e1601871','ch_ea65f5bf88df','text','{"text": "about ten o’clock. I had my meal at the restaurant and returned to my room. I heard a noise from above as I opened the door. The sound was a familiar one. One could say that the rats and I shared the room. I took out my box of matches and lighted the kerosene lamp on the table."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_680ccdd92355','ch_ea65f5bf88df','text','{"text": "The house was not electrified;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b45a7e289162','ch_ea65f5bf88df','text','{"text": "it was a small rented room. I had just set up medical practice and my earnings were meagre. I had about sixty rupees in my suitcase. Along with some shirts and dhotis, I also possessed one solitary black coat which I was then wearing. I took off my black coat, white shirt and not-sowhite vest and hung them up. I opened the two windows in the room. It was an outer room with one wall facing the open yard."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_759334440124','ch_ea65f5bf88df','text','{"text": "It had a tiled roof with long supporting gables that rested on the beam over the wall. There was no ceiling. There was a regular traffic of rats to and from the beam. I made my bed and pulled it close to the wall. I lay down but I could not sleep. I got up and went out to the veranda for a little air, but the wind god seemed to have taken time off. I went back into the room and sat down on the chair. I opened the box beneath the table and took out a book, the Materia Medica."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab2ca24ee19e','ch_ea65f5bf88df','text','{"text": "I opened it at the table on which stood the lamp and a large mirror;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4ac41ee0af1','ch_ea65f5bf88df','text','{"text": "a small comb lay beside the mirror. One feels tempted to look into a mirror when it is near one. I took a look. In those days I was a great admirer of beauty and I believed in making myself look handsome. I was unmarried and I was a doctor. I felt I had to make my presence felt. I picked up the comb and ran it through my hair and adjusted the parting so that it looked straight and neat. Again I heard that sound from above."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6170f5fb8b1','ch_ea65f5bf88df','text','{"text": "I took a close look at my face in the mirror. I made an important decision — I would shave daily and grow a thin moustache to look more handsome. I was after all a bachelor, and a doctor! I looked into the mirror and smiled. It was an attractive smile. I made another earth-shaking decision. I would always keep that attractive smile on my face . .. to look more handsome. I was after all a bachelor, and a doctor too on top of it! Again came that noise from above."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17d9d963af8e','ch_ea65f5bf88df','text','{"text": "I got up, paced up and down the room. Then another lovely thought struck me. I would marry. I would get married to a woman doctor who had plenty of money and a good medical practice. She had to be fat;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c3ccc2296b5','ch_ea65f5bf88df','text','{"text": "for a valid reason. If I made some silly mistake and needed to run away she should not be able to run after me and catch me! With such thoughts in my mind I resumed my seat in the chair in front of the table. There were no more sounds from above."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0fc7d38ea04','ch_ea65f5bf88df','text','{"text": "Suddenly there came a dull thud as if a rubber tube had fallen to the ground ... surely nothing to worry about. Even so I thought I would turn around and take a look. No sooner had I turned than a fat snake wriggled over the back of the chair and landed on my shoulder. The snake’s landing on me and my turning were simultaneous. I didn’t jump. I didn’t tremble. I didn’t cry out. There was no time to do any such thing."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_087701090585','ch_ea65f5bf88df','text','{"text": "The snake slithered along my shoulder and coiled around my left arm above the elbow. The hood was spread out and its head was hardly three or four inches from my face! It would not be correct to say merely that I sat there holding my breath. I was turned to stone. But my mind was very active. The door opened into darkness. The room was surrounded by darkness. In the light of the lamp I sat there like a stone image in the flesh."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d1c353d9d00','ch_ea65f5bf88df','text','{"text": "I felt then the great presence of the creator of this world and this universe. God was there. Suppose I said something and he did not like it . .. I tried in my imagination to write in bright letters outside my little heart the words, ‘O God’. There was some pain in my left arm. It was as if a thick leaden rod — no, a rod made of molten fire — was slowly but powerfully crushing my arm. The arm was beginning to be drained of all strength."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0839d99eb981','ch_ea65f5bf88df','text','{"text": "What could I do? At my slightest movement the snake would strike me! Death lurked four inches away. Suppose it struck, what was the medicine I had to take? There were no medicines in the room. I was but a poor, foolish and stupid doctor. I forgot my danger and smiled feebly at myself. It seemed as if God appreciated that. The snake turned its head. It looked into the mirror and saw its reflection. I do not claim that it was the first snake that had ever looked into a mirror."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8fd88d0e17e','ch_ea65f5bf88df','text','{"text": "But it was certain that the snake was looking into the mirror. Was it admiring its own beauty? Was it trying to make an important decision about growing a moustache or using eye shadow and mascara or wearing a vermilion spot on its forehead? I did not know anything for certain. What sex was this snake, was it male or female? I will never know;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_777b62e0f315','ch_ea65f5bf88df','text','{"text": "for the snake unwound itself from my arm and slowly slithered into my lap. From there it crept onto the table and moved towards the mirror."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3107136057ed','ch_ea65f5bf88df','text','{"text": "Perhaps it wanted to enjoy its reflection at closer quarters. I was no mere image cut in granite. I was suddenly a man of flesh and blood. Still holding my breath I got up from the chair. I quietly went out through the door into the veranda. From there I leapt into the yard and ran for all I was worth."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91950c26c0c1','ch_ea65f5bf88df','text','{"text": "‘Phew !’ Each of us heaved a sigh of relief. Somebody asked, ‘Doctor, is your wife very fat?’"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0dfa05149cb','ch_ea65f5bf88df','text','{"text": "‘No,’ the doctor said."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c46da1dc2261','ch_ea65f5bf88df','text','{"text": "‘God willed otherwise. My life companion is a thin reedy person with the gift of a sprinter.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5b5d35a74a0','ch_ea65f5bf88df','text','{"text": "Someone else asked, ‘Doctor, when you ran did the snake follow you?’ The doctor replied, ‘I ran and ran till I reached a friend’s house. Immediately I smeared oil all over myself and took a bath. I changed into fresh clothes. The next morning at about eight-thirty I took my friend and one or two others to my room to move my things from there. But we found we had little to carry. Some thief had removed most of my things."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d2fbb5bdb345','ch_ea65f5bf88df','text','{"text": "The room had been cleaned out! But not really, the thief had left behind one thing as a final insult!’"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd1c27828ac5','ch_ea65f5bf88df','text','{"text": "‘What was that?’ I asked."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84f918ead9dc','ch_ea65f5bf88df','text','{"text": "The doctor said, ‘My vest, the dirty one. The fellow had such a sense of cleanliness...! The rascal could have taken it and used it after washing it with soap and water.’"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95b7d408f9a7','ch_ea65f5bf88df','text','{"text": "‘Did you see the snake the next day, doctor?’ The doctor laughed, ‘I’ve never seen it since."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f1a4c69f4183','ch_ea65f5bf88df','text','{"text": "It was a snake which was taken with its own beauty!’"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1586e76bc7e','ch_ea65f5bf88df','heading','{"level": 2, "text": "Vaikom Muhammad Basheer"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4253e4b2006e','ch_ea65f5bf88df','text','{"text": "[translated from the Malayalam by V. Abdulla]"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2538029e2fb2','ch_ea65f5bf88df','text','{"text": "*********"}',30);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b63f4c33939c','bk_ncert_english','9-9-a-legend-of-the-northland','9.9 A Legend of the Northland',NULL,'public',9,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c95a60b63085','ch_b63f4c33939c','text','{"text": "Away, away in the Northland,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2322fe409c5d','ch_b63f4c33939c','text','{"text": "Where the hours of the day are few,"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1934ed918a20','ch_b63f4c33939c','text','{"text": "And the nights are so long in winter"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62c8a952ee38','ch_b63f4c33939c','text','{"text": "That they cannot sleep them through;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b15d26d6c1f','ch_b63f4c33939c','text','{"text": "Where they harness the swift reindeer"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fc37360c9aab','ch_b63f4c33939c','text','{"text": "To the sledges, when it snows;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f6389c89f5a5','ch_b63f4c33939c','text','{"text": "And the children look like bear’s cubs"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a21f3cc19947','ch_b63f4c33939c','text','{"text": "In their funny, furry clothes:"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_211221681834','ch_b63f4c33939c','text','{"text": "They tell them a curious story —"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0057fe9a4b29','ch_b63f4c33939c','text','{"text": "I don’t believe ’tis true;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ece4585c8a3','ch_b63f4c33939c','text','{"text": "And yet you may learn a lesson"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_25b4971eabe7','ch_b63f4c33939c','text','{"text": "If I tell the tale to you."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_706497c1c4ab','ch_b63f4c33939c','text','{"text": "Once, when the good Saint Peter"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aeed47596e6a','ch_b63f4c33939c','text','{"text": "Lived in the world below,"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9dc6b26804ea','ch_b63f4c33939c','text','{"text": "And walked about it, preaching,"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b99197872c03','ch_b63f4c33939c','text','{"text": "Just as he did, you know,"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18007b07d4a7','ch_b63f4c33939c','text','{"text": "He came to the door of a cottage,"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b458102bb5e','ch_b63f4c33939c','text','{"text": "In travelling round the earth,"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_297da1e316a9','ch_b63f4c33939c','text','{"text": "Where a little woman was making cakes,"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_233d50c4f243','ch_b63f4c33939c','text','{"text": "And baking them on the hearth;"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_805be71cd390','ch_b63f4c33939c','text','{"text": "And being faint with fasting,"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd96675fc41f','ch_b63f4c33939c','text','{"text": "For the day was almost done,"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e6968579fb27','ch_b63f4c33939c','text','{"text": "He asked her, from her store of cakes,"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b6240345bff','ch_b63f4c33939c','text','{"text": "To give him a single one."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_affba45fe5cb','ch_b63f4c33939c','text','{"text": "So she made a very little cake,"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0b20f9a1f74e','ch_b63f4c33939c','text','{"text": "But as it baking lay,"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_850afe45689b','ch_b63f4c33939c','text','{"text": "She looked at it, and thought it seemed"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9844070684af','ch_b63f4c33939c','text','{"text": "Too large to give away."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0990bfd92d48','ch_b63f4c33939c','text','{"text": "Therefore she kneaded another,"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98d8425ac840','ch_b63f4c33939c','text','{"text": "And still a smaller one;"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d5bc799d309','ch_b63f4c33939c','text','{"text": "But it looked, when she turned it over,"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f81a61a8d83e','ch_b63f4c33939c','text','{"text": "As large as the first had done."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab1f284eb78e','ch_b63f4c33939c','text','{"text": "Then she took a tiny scrap of dough,"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2af3d5486e55','ch_b63f4c33939c','text','{"text": "And rolled and rolled it flat;"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ba935903461','ch_b63f4c33939c','text','{"text": "And baked it thin as a wafer —"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c99795604c7a','ch_b63f4c33939c','text','{"text": "But she couldn’t part with that."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c4b93f856343','ch_b63f4c33939c','text','{"text": "For she said, “My cakes that seem too small"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_17bacc67ad3c','ch_b63f4c33939c','text','{"text": "When I eat of them myself"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8cf56a9de6f6','ch_b63f4c33939c','text','{"text": "Are yet too large to give away.”"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_80050c7093c2','ch_b63f4c33939c','text','{"text": "So she put them on the shelf."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_682f024e189b','ch_b63f4c33939c','text','{"text": "Then good Saint Peter grew angry,"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ecb030613db5','ch_b63f4c33939c','text','{"text": "For he was hungry and faint;"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9c7ee1d50a6c','ch_b63f4c33939c','text','{"text": "And surely such a woman"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89ec50a46dac','ch_b63f4c33939c','text','{"text": "Was enough to provoke a saint."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_261bfd26621c','ch_b63f4c33939c','text','{"text": "And he said, “You are far too selfish"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08f4b9708592','ch_b63f4c33939c','text','{"text": "To dwell in a human form,"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ddd2d317add8','ch_b63f4c33939c','text','{"text": "To have both food and shelter,"}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_62a5ace52f07','ch_b63f4c33939c','text','{"text": "And fire to keep you warm."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0d50024d3fa6','ch_b63f4c33939c','text','{"text": "Now, you shall build as the birds do,"}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c1d38fd93fd','ch_b63f4c33939c','text','{"text": "And shall get your scanty food"}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c84d08d6fa73','ch_b63f4c33939c','text','{"text": "By boring, and boring, and boring,"}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad0cd5295779','ch_b63f4c33939c','text','{"text": "All day in the hard, dry wood.”"}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9dc4251ab539','ch_b63f4c33939c','text','{"text": "Then up she went through the chimney,"}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b53b821dfd13','ch_b63f4c33939c','text','{"text": "Never speaking a word,"}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a5dad7375c90','ch_b63f4c33939c','text','{"text": "And out of the top flew a woodpecker,"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8db122ce68f4','ch_b63f4c33939c','text','{"text": "For she was changed to a bird."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6092971f0be3','ch_b63f4c33939c','text','{"text": "She had a scarlet cap on her head,"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b18a21079f7','ch_b63f4c33939c','text','{"text": "And that was left the same;"}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1011383efae','ch_b63f4c33939c','text','{"text": "But all the rest of her clothes were burned"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b4c940971ec','ch_b63f4c33939c','text','{"text": "Black as a coal in the flame."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e567a1cfc208','ch_b63f4c33939c','text','{"text": "And every country schoolboy"}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7dc529f1f23d','ch_b63f4c33939c','text','{"text": "Has seen her in the wood,"}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_075484d027ae','ch_b63f4c33939c','text','{"text": "Where she lives in the trees till this very day,"}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_59d60330dea2','ch_b63f4c33939c','text','{"text": "Boring and boring for food."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0fd11e31e7b1','ch_b63f4c33939c','heading','{"level": 2, "text": "Phoebe Cary"}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_701cf156c055','ch_b63f4c33939c','text','{"text": "*********"}',66);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_56cef8804d4d','bk_ncert_english','9-10-my-childhood','9.10 My Childhood',NULL,'public',10,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b0b508b19920','ch_56cef8804d4d','text','{"text": "I WAS born into a middle-class Tamil family in the island town of Rameswaram in the erstwhile Madras State. My father, Jainulabdeen, had neither much formal education nor much wealth;"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ba7d95a2508','ch_56cef8804d4d','text','{"text": "despite these disadvantages, he possessed great innate wisdom and a true generosity of spirit. He had an ideal helpmate in my mother, Ashiamma."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_127a75f1d815','ch_56cef8804d4d','text','{"text": "I do not recall the exact number of people she fed every day, but I am quite certain that far more outsiders ate with us than all the members of our own family put together. I was one of many children — a short boy with rather undistinguished looks, born to tall and handsome parents. We lived in our ancestral house, which was built in the middle of the nineteenth century. It was a fairly large pucca house, made of limestone and brick, on the Mosque Street in Rameswaram."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1df09b1ec0d4','ch_56cef8804d4d','text','{"text": "My austere father used to avoid all inessential comforts and luxuries. However, all necessities were provided for, in terms of food, medicine or clothes. In fact, I would say mine was a very secure childhood, both materially and emotionally. The Second World War broke out in 1939, when I was eight years old. For reasons I have never been able to understand, a sudden demand for tamarind seeds erupted in the market. I used to collect the seeds and sell them to a provision shop on Mosque Street."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a7733a565bc8','ch_56cef8804d4d','text','{"text": "A day’s collection would fetch me the princely sum of one anna. My brother-in-law Jallaluddin would tell me stories about the War which I would later attempt to trace in the headlines in Dinamani. Our area, being isolated, was completely unaffected by the War. But soon India was forced to join the Allied Forces and something like a state of emergency was declared. The first casualty came in the form of the suspension of the train halt at Rameswaram station."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d2ae0f53c41','ch_56cef8804d4d','text','{"text": "The newspapers now had to be bundled and thrown out from the moving train on the Rameswaram Road between Rameswaram and Dhanuskodi. That forced my cousin Samsuddin, who distributed newspapers in Rameswarm, to look for a helping hand to catch the bundles and, as if naturally, I filled the slot. Samsuddin helped me earn my first wages. Half a century later, I can still feel the surge of pride in earning my own money for the first time."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8354d2b32cef','ch_56cef8804d4d','text','{"text": "Every child is born, with some inherited characteristics, into a specific socio-economic and emotional environment, and trained in certain ways by figures of authority. I inherited honesty and self discipline from my father;"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ccd0ac33c99','ch_56cef8804d4d','text','{"text": "from my mother, I inherited faith in goodness and deep kindness and so did my three brothers and sister. I had three close friends in my childhood — Ramanadha Sastry, Aravindan and Sivaprakasan. All these boys were from orthodox Hindu Brahmin families."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_802ae1467e2c','ch_56cef8804d4d','text','{"text": "As children, none of us ever felt any difference amongst ourselves because of our religious differences and upbringing. In fact, Ramanadha Sastry was the son of Pakshi Lakshmana Sastry, the high priest of the Rameswaram temple. Later, he took over the priesthood of the Rameswaram temple from his father;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3ad85cd05226','ch_56cef8804d4d','text','{"text": "Aravindan went into the business of arranging transport for visiting pilgrims;"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1cb3b0e8323','ch_56cef8804d4d','text','{"text": "and Sivaprakasan became a catering contractor for the Southern Railways."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d913dace3245','ch_56cef8804d4d','text','{"text": "During the annual Shri Sita Rama Kalyanam ceremony, our family used to arrange boats with a special platform for carrying idols of the Lord from the temple to the marriage site, situated in the middle of the pond called Rama Tirtha which was near our house. Events from the Ramayana and from the life of the Prophet were the bedtime stories my mother and grandmother would tell the children in our family. 6."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cf07ea874520','ch_56cef8804d4d','text','{"text": "One day when I was in the fifth standard at the Rameswaram Elementary School, a new teacher came to our class. I used to wear a cap which marked me as a Muslim, and I always sat in the front row next to Ramanadha Sastry, who wore the sacred thread. The new teacher could not stomach a Hindu priest’s son sitting with a Muslim boy. In accordance with our social ranking as the new teacher saw it, I was asked to go and sit on the back bench. I felt very sad, and so did Ramanadha Sastry."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ce83aae1501','ch_56cef8804d4d','text','{"text": "He looked utterly downcast as I shifted to my seat in the last row. The image of him weeping when I shifted to the last row left a lasting impression on me. After school, we went home and told our respective parents about the incident. Lakshmana Sastry summoned the teacher, and in our presence, told the teacher that he should not spread the poison of social inequality and communal intolerance in the minds of innocent children."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9d2b61ba695','ch_56cef8804d4d','text','{"text": "He bluntly asked the teacher to either apologise or quit the school and the island. Not only did the teacher regret his behaviour, but the strong sense of conviction Lakshmana Sastry conveyed ultimately reformed this young teacher. On the whole, the small society of Rameswaram was very rigid in terms of the segregation of different social groups. However, my science teacher Sivasubramania Iyer, though an orthodox Brahmin with a very conservative wife, was something of a rebel."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_384f0b660005','ch_56cef8804d4d','text','{"text": "He did his best to break social barriers so that people from varying backgrounds could mingle easily. He used to spend hours with me and would say, ‘Kalam, I want you to develop so that you are on par with the highly educated people of the big cities.’"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ac7d58cd421','ch_56cef8804d4d','text','{"text": "One day, he invited me to his home for a meal. His wife was horrified at the idea of a Muslim boy being invited to dine in her ritually pure kitchen. She refused to serve me in her kitchen. Sivasubramania Iyer was not perturbed, nor did he get angry with his wife, but instead, served me with his own hands and sat down beside me to eat his meal. His wife watched us from behind the kitchen door."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6ca1b9067acc','ch_56cef8804d4d','text','{"text": "I wondered whether she had observed any difference in the way I ate rice, drank water or cleaned the floor after the meal. When I was leaving his house, Sivasubramania Iyer invited me to join him for dinner again the next weekend. Observing my hesitation, he told me not to get upset, saying, ‘Once you decide to change the system, such problems have to be confronted.’"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a36d5dc67d97','ch_56cef8804d4d','text','{"text": "When I visited his house the next week, Sivasubramania Iyer’s wife took me inside her kitchen and served me food with her own hands. Then the Second World War was over and India’s freedom was imminent."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ac7fa429d5e','ch_56cef8804d4d','text','{"text": "‘Indians will build their own India,’ declared Gandhiji."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b995f2e9d20','ch_56cef8804d4d','text','{"text": "The whole country was filled with an unprecedented optimism. I asked my father for permission to leave Rameswaram and study at the district headquarters in Ramanathapuram. He told me as if thinking aloud, ‘Abul ! I know you have to go away to grow. Does the seagull not fly across the sun, alone and without a nest?’ He quoted Khalil Gibran to my hesitant mother, ‘Your children are not your children. They are the sons and daughters of Life’s longing for itself."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39a7eceeeaca','ch_56cef8804d4d','text','{"text": "They come through you but not from you. You may give them your love but not your thoughts. For they have their own thoughts.’"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7d68374a146','ch_56cef8804d4d','heading','{"level": 2, "text": "A.P.J. Abdul Kalam"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1bd0ae682cce','ch_56cef8804d4d','text','{"text": "[an extract from Wings of Fire]"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0480f5cdabe','ch_56cef8804d4d','text','{"text": "*********"}',25);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_ad86193521bc','bk_ncert_english','9-11-no-men-are-foreign','9.11 No Men Are Foreign',NULL,'public',11,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b660f918571','ch_ad86193521bc','text','{"text": "Remember, no men are strange, no countries foreign"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_95e5a5b6f34f','ch_ad86193521bc','text','{"text": "Beneath all uniforms, a single body breathes"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa0c47b82d7a','ch_ad86193521bc','text','{"text": "Like ours: the land our brothers walk upon"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab4fa7e38d04','ch_ad86193521bc','text','{"text": "Is earth like this, in which we all shall lie."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8ea4e215bc7','ch_ad86193521bc','text','{"text": "They, too, aware of sun and air and water,"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9bfea481405d','ch_ad86193521bc','text','{"text": "Are fed by peaceful harvests, by war’s long winter starv’d."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ff26f1e32ea','ch_ad86193521bc','text','{"text": "Their hands are ours, and in their lines we read"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9fcc3b5a781e','ch_ad86193521bc','text','{"text": "A labour not different from our own."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9cb96214c820','ch_ad86193521bc','text','{"text": "Remember they have eyes like ours that wake"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48a61f53416f','ch_ad86193521bc','text','{"text": "Or sleep, and strength that can be won"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0ceb3268b25e','ch_ad86193521bc','text','{"text": "By love. In every land is common life"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48c896932260','ch_ad86193521bc','text','{"text": "That all can recognise and understand."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1fc474b0466c','ch_ad86193521bc','text','{"text": "Let us remember, whenever we are told"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f336b100a60c','ch_ad86193521bc','text','{"text": "To hate our brothers, it is ourselves"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_32c61353c691','ch_ad86193521bc','text','{"text": "That we shall dispossess, betray, condemn."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ffef52d5ccdd','ch_ad86193521bc','text','{"text": "Remember, we who take arms against each other"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_45fd85006be0','ch_ad86193521bc','text','{"text": "It is the human earth that we defile."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_40b624a4807d','ch_ad86193521bc','text','{"text": "Our hells of fire and dust outrage the innocence"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_edf75a7bdd63','ch_ad86193521bc','text','{"text": "Of air that is everywhere our own,"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fdfb0d93a0ba','ch_ad86193521bc','text','{"text": "Remember, no men are foreign, and no countries strange."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d45989707129','ch_ad86193521bc','heading','{"level": 2, "text": "James Kirkup"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7cd181d0a4a2','ch_ad86193521bc','text','{"text": "*********"}',22);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_90ac41ba633a','bk_ncert_english','9-12-packing','9.12 Packing',NULL,'public',12,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_460276a3acc3','ch_90ac41ba633a','text','{"text": "I SAID I’d pack. I rather pride myself on my packing. Packing is one of those many things that I feel I know more about than any other person living. (It surprises me myself, sometimes, how many such things there are.)"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_33fae9635f88','ch_90ac41ba633a','text','{"text": "I impressed the fact upon George and Harris and told them that they had better leave the whole matter entirely to me. They fell into the suggestion with a readiness that had something uncanny about it. George spread himself over the easy-chair, and Harris cocked his legs on the table. This was hardly what I intended."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_31799017ce2c','ch_90ac41ba633a','text','{"text": "What I had meant, of course, was, that I should boss the job, and that Harris and George should potter about under my directions, I pushing them aside every now and then with, ‘Oh, you!’"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd1de19c46c6','ch_90ac41ba633a','text','{"text": "‘Here, let me do it.’"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_365d6e4e6a1b','ch_90ac41ba633a','text','{"text": "‘There you are, simple enough!’ — really teaching them, as you might say."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5003b26826ad','ch_90ac41ba633a','text','{"text": "Their taking it in the way they did irritated me. There is nothing does irritate me more than seeing other people sitting about doing nothing when I’m working. I lived with a man once who used to make me mad that way. He would loll on the sofa and watch me doing things by the hour together. He said it did him real good to look on at me, messing about. Now, I’m not like that. I can’t sit still and see another man slaving and working."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_466e4810e602','ch_90ac41ba633a','text','{"text": "I want to get up and superintend, and walk round with my hands in my pockets, and tell him what to do. It is my energetic nature. I can’t help it. However, I did not say anything, but started the packing. It seemed a longer job than I had thought it was going to be; but I got the bag finished at last, and I sat on it and strapped it."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_889b0fd28d79','ch_90ac41ba633a','text','{"text": "‘Ain’t you going to put the boots in?’ said Harris. And I looked round, and found I had forgotten them. That’s just like Harris. He couldn’t have said a word until I’d got the bag shut and strapped, of course. And George laughed — one of those irritating, senseless laughs of his. They do make me so wild. I opened the bag and packed the boots in; and then, just as I was going to close it, a horrible idea occurred to me."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b0541a75f34','ch_90ac41ba633a','text','{"text": "Had I packed my toothbrush? I don’t know how it is, but I never do know whether I’ve packed my toothbrush. My toothbrush is a thing that haunts me when I’m travelling, and makes my life a misery. I dream that I haven’t packed it, and wake up in a cold perspiration, and get out of bed and hunt for it."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e276e2182c5c','ch_90ac41ba633a','text','{"text": "And, in the morning, I pack it before I have used it, and have to unpack again to get it, and it is always the last thing I turn out of the bag; and then I repack and forget it, and have to rush upstairs for it at the last moment and carry it to the railway station, wrapped up in my pocket-handkerchief. Of course I had to turn every mortal thing out now, and, of course, I could not find it."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7d2f374a055','ch_90ac41ba633a','text','{"text": "I rummaged the things up into much the same state that they must have been before the world was created, and when chaos reigned. Of course, I found George’s and Harris’s eighteen times over, but I couldn’t find my own. I put the things back one by one, and held everything up and shook it. Then I found it inside a boot. I repacked once more. When I had finished, George asked if the soap was in."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cb971fa9fdb1','ch_90ac41ba633a','text','{"text": "I said I didn’t care a hang whether the soap was in or whether it wasn’t; and I slammed the bag shut and strapped it, and found that I had packed my spectacles in it, and had to re-open it. It got shut up finally at 10.05 p.m., and then there remained the hampers to do. Harris said that we should be wanting to start in less than twelve hours’ time and thought that he and George had better do the rest; and I agreed and sat down, and they had a go."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06fedd0f20f3','ch_90ac41ba633a','text','{"text": "They began in a light-hearted spirit, evidently intending to show me how to do it. I made no comment; I only waited. With the exception of George, Harris is the worst packer in this world; and I looked at the piles of plates and cups, and kettles, and bottles, and jars, and pies, and stoves, and cakes, and tomatoes, etc., and felt that the thing would soon become exciting. It did. They started with breaking a cup. That was the first thing they did."}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77c219135b69','ch_90ac41ba633a','text','{"text": "They did that just to show you what they could do, and to get you interested. Then Harris packed the strawberry jam on top of a tomato and squashed it, and they had to pick out the tomato with a teaspoon. And then it was George’s turn, and he trod on the butter. I didn’t say anything, but I came over and sat on the edge of the table and watched them. It irritated them more than anything I could have said. I felt that."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8baf7c486a1d','ch_90ac41ba633a','text','{"text": "It made them nervous and excited, and they stepped on things, and put things behind them, and then couldn’t find them when they wanted them; and they packed the pies at the bottom, and put heavy things on top, and smashed the pies in. They upset salt over everything, and as for the butter! I never saw two men do more with one-and two pence worth of butter in my whole life than they did. After George had got it off his slipper, they tried to put it in the kettle."}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_735c36938311','ch_90ac41ba633a','text','{"text": "It wouldn’t go in, and what was in wouldn’t come out. They did scrape it out at last, and put it down on a chair, and Harris sat on it, and it stuck to him, and they went looking for it all over the room."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_63b24e4a5274','ch_90ac41ba633a','text','{"text": "‘I’ll take my oath I put it down on that chair,’ said George, staring at the empty seat."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_991e365df627','ch_90ac41ba633a','text','{"text": "‘I saw you do it myself, not a minute ago,’ said Harris."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_654c87106093','ch_90ac41ba633a','text','{"text": "Then they started round the room again looking for it; and then they met again in the centre and stared at one another."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc1a1557c708','ch_90ac41ba633a','text','{"text": "‘Most extraordinary thing I ever heard of,’ said George."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b5314d25f772','ch_90ac41ba633a','text','{"text": "‘So mysterious!’ said Harris."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_22b0a0096945','ch_90ac41ba633a','text','{"text": "Then George got round at the back of Harris and saw it."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_367da92a4f7c','ch_90ac41ba633a','text','{"text": "‘Why, here it is all the time,’ he exclaimed, indignantly."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_807862962d5c','ch_90ac41ba633a','text','{"text": "‘Where?’ cried Harris, spinning round."}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7a7d2b465501','ch_90ac41ba633a','text','{"text": "‘Stand still, can’t you!’ roared George, flying after him."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a52dad6d8d0e','ch_90ac41ba633a','text','{"text": "And they got it off, and packed it in the teapot. Montmorency was in it all, of course. Montmorency’s ambition in life is to get in the way and be sworn at. If he can squirm in anywhere where he particularly is not wanted, and be a perfect nuisance, and make people mad, and have things thrown at his head, then he feels his day has not been wasted."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a08ae0c1fa67','ch_90ac41ba633a','text','{"text": "To get somebody to stumble over him, and curse him steadily for an hour, is his highest aim and object; and, when he has succeeded in accomplishing this, his conceit becomes quite unbearable. He came and sat down on things, just when they were wanted to be packed; and he laboured under the fixed belief that, whenever Harris or George reached out their hand for anything, it was his cold damp nose that they wanted."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4bf1d8cd448a','ch_90ac41ba633a','text','{"text": "He put his leg into the jam, and he worried the teaspoons, and he pretended that the lemons were rats, and got into the hamper and killed three of them before Harris could land him with the frying-pan. Harris said I encouraged him. I didn’t encourage him. A dog like that doesn’t want any encouragement. It’s the natural, original sin that is born in him that makes him do things like that. The packing was done at 12.50;"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e9ab93755b0','ch_90ac41ba633a','text','{"text": "and Harris sat on the big hamper, and said he hoped nothing would be found broken. George said that if anything was broken it was broken, which reflection seemed to comfort him. He also said he was ready for bed. We were all ready for bed. Harris was to sleep with us that night, and we went upstairs. 15. We tossed for beds, and Harris had to sleep with me. He said :"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_579004010db5','ch_90ac41ba633a','text','{"text": "‘Do you prefer the inside or the outside, J.?’ I said I generally preferred to sleep inside a bed. Harris said it was odd. George said:"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_91109ecdd20b','ch_90ac41ba633a','text','{"text": "‘What time shall I wake you fellows?’ Harris said:"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28d104c4924c','ch_90ac41ba633a','text','{"text": "‘Seven.’"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6eeb3bde2954','ch_90ac41ba633a','text','{"text": "I said:"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3fcc712c003a','ch_90ac41ba633a','text','{"text": "‘No — six,’ because I wanted to write some letters."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d18cecd2e7bb','ch_90ac41ba633a','text','{"text": "Harris and I had a bit of a row over it, but at last split the difference, and said half-past six."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c383eebc9755','ch_90ac41ba633a','text','{"text": "‘Wake us at 6.30, George,’ we said. George made no answer, and we found, on going over, that he had been asleep for sometime; so we placed the bath where he could tumble into it on getting out in the morning, and went to bed ourselves."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58ffd6757f38','ch_90ac41ba633a','heading','{"level": 2, "text": "Jerome K. Jerome"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_869dde61b8e1','ch_90ac41ba633a','text','{"text": "[an extract from Three Men in a Boat]"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_715735b566bb','ch_90ac41ba633a','text','{"text": "*********"}',39);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_066738f09ad8','bk_ncert_english','9-13-the-duck-and-the-kangaroo','9.13 The Duck and the Kangaroo',NULL,'public',13,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e616e98498e','ch_066738f09ad8','heading','{"level": 2, "text": "I"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_144d64a810d2','ch_066738f09ad8','text','{"text": "Said the Duck to the Kangaroo,"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad87303df183','ch_066738f09ad8','text','{"text": "“Good gracious! how you hop!"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7fd3812a6890','ch_066738f09ad8','text','{"text": "Over the fields and the water too,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_19f90f6508a4','ch_066738f09ad8','text','{"text": "As if you never would stop!"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd29ec9b3062','ch_066738f09ad8','text','{"text": "My life is a bore in this nasty pond,"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6b960d87ba6c','ch_066738f09ad8','text','{"text": "And I long to go out in the world beyond!"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2f4255964d7c','ch_066738f09ad8','text','{"text": "I wish I could hop like you!”"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6262d7ed917c','ch_066738f09ad8','text','{"text": "Said the Duck to the Kangaroo."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b206d9c696e','ch_066738f09ad8','heading','{"level": 2, "text": "Ii"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de2b4e8e0e49','ch_066738f09ad8','text','{"text": "“Please give me a ride on your back!”"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_006af6f26155','ch_066738f09ad8','text','{"text": "Said the Duck to the Kangaroo."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5000ec34dd38','ch_066738f09ad8','text','{"text": "“I would sit quite still, and say nothing but ‘Quack’,"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d54669e8a7fd','ch_066738f09ad8','text','{"text": "The whole of the long day through!"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c2f2a85f25d','ch_066738f09ad8','text','{"text": "And we’d go to the Dee, and the Jelly Bo Lee,"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d706a63bfe56','ch_066738f09ad8','text','{"text": "Over the land, and over the sea;"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ff927316b2a4','ch_066738f09ad8','text','{"text": "Please take me a ride! O do!”"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_edcd4887b474','ch_066738f09ad8','text','{"text": "Said the Duck to the Kangaroo."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_53b742cb29fb','ch_066738f09ad8','heading','{"level": 2, "text": "Iii"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c717bc7925a','ch_066738f09ad8','text','{"text": "Said the Kangaroo to the Duck,"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_636d8240d75b','ch_066738f09ad8','text','{"text": "“This requires some little reflection;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0023250fc6b9','ch_066738f09ad8','text','{"text": "Perhaps on the whole it might bring me luck,"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_211e5a131b48','ch_066738f09ad8','text','{"text": "And there seems but one objection,"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5265dfb79695','ch_066738f09ad8','text','{"text": "Which is, if you’ll let me speak so bold,"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38de3c107bb3','ch_066738f09ad8','text','{"text": "Your feet are unpleasantly wet and cold,"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9858a6ac4c5e','ch_066738f09ad8','text','{"text": "And would probably give me the roo-"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_671516333eb8','ch_066738f09ad8','text','{"text": "Matiz!” said the Kangaroo."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_941c42e9bdaa','ch_066738f09ad8','heading','{"level": 2, "text": "Iv"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ee61feff888','ch_066738f09ad8','text','{"text": "Said the Duck, “As I sat on the rocks,"}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b685705c8aac','ch_066738f09ad8','text','{"text": "I have thought over that completely,"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6037d84ee54e','ch_066738f09ad8','text','{"text": "And I bought four pairs of worsted socks"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8c4b6777d2c','ch_066738f09ad8','text','{"text": "Which fit my web-feet neatly."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bc67bdc2d188','ch_066738f09ad8','text','{"text": "And to keep out the cold I’ve bought a cloak,"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c9dc7305b858','ch_066738f09ad8','text','{"text": "And every day a cigar I’ll smoke,"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c1263696d814','ch_066738f09ad8','text','{"text": "All to follow my own dear true"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01b8b722adb4','ch_066738f09ad8','text','{"text": "Love of a Kangaroo!”"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f88b77ba7395','ch_066738f09ad8','heading','{"level": 2, "text": "V"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98c3c8bd896d','ch_066738f09ad8','text','{"text": "Said the Kangaroo, “I’m ready!"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b27338fe0bc','ch_066738f09ad8','text','{"text": "All in the moonlight pale;"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5394b6659d38','ch_066738f09ad8','text','{"text": "But to balance me well, dear Duck, sit steady!"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c414ff76f632','ch_066738f09ad8','text','{"text": "And quite at the end of my tail!”"}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8c5cedbbab73','ch_066738f09ad8','text','{"text": "So away they went with a hop and a bound,"}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a34993e24ad0','ch_066738f09ad8','text','{"text": "And they hopped the whole world three times round;"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0da50934594d','ch_066738f09ad8','text','{"text": "And who so happy — O who,"}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2d9ef3e08c3','ch_066738f09ad8','text','{"text": "As the Duck and the Kangaroo?"}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b6ca76964009','ch_066738f09ad8','text','{"text": "Edward Lear"}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_33b68688fca4','ch_066738f09ad8','text','{"text": "*********"}',47);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_8115c7e6aac6','bk_ncert_english','9-14-reach-for-the-top','9.14 Reach for the Top',NULL,'public',14,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_27419f3ddaa8','ch_8115c7e6aac6','text','{"text": "Part I"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2273df4a6d84','ch_8115c7e6aac6','text','{"text": "Santosh Yadav"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dbfb44e009be','ch_8115c7e6aac6','text','{"text": "The only woman in the world who has scaled Mt Everest twice was born in a society where the birth of a son was regarded as a blessing, and a daughter, though not considered a curse, was not generally welcome. When her mother was expecting Santosh, a travelling"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b31c7bfb642b','ch_8115c7e6aac6','text','{"text": "‘holy man’, giving her his blessing, assumed that she wanted a son."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c3b07636506','ch_8115c7e6aac6','text','{"text": "But, to everyone’s surprise, the unborn child’s grandmother, who was standing close by, told him that they did not want a son. The"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_41f4e18038dc','ch_8115c7e6aac6','text','{"text": "‘holy man’ was also surprised! Nevertheless, he gave the requested blessing ."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fecb16e4eaa3','ch_8115c7e6aac6','text','{"text": ". . and as destiny would have it, the blessing seemed to work. Santosh was born the sixth child in a family with five sons, a sister to five brothers. She was born in the small village of Joniyawas of Rewari District in Haryana. The girl was given the name"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_022472b3e12f','ch_8115c7e6aac6','text','{"text": "‘Santosh’, which means contentment. But Santosh was not always content with her place in a traditional way of life. She began living life on her own terms from the start. Where other girls wore traditional Indian dresses, Santosh preferred shorts. Looking back, she says now, ‘From the very beginning I was quite determined that if I chose a correct and a rational path, the others around me had to change, not me.’"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a994d6e33473','ch_8115c7e6aac6','text','{"text": "Santosh’s parents were affluent landowners who could afford to send their children to the best schools, even to the country’s capital, New Delhi, which was quite close by. But, in line with the prevailing custom in the family, Santosh had to make do with the local village school. So, she decided to fight the system in her own quiet way when the right moment arrived. And the right moment came when she turned sixteen. At sixteen, most of the girls in her village used to get married."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94ab78b68d83','ch_8115c7e6aac6','text','{"text": "Santosh was also under pressure from her parents to do the same. A marriage as early as that was the last thing on her mind. She threatened her parents that she would never marry if she did not get a proper education. She left home and got herself enrolled in a school in Delhi. When her parents refused to pay for her education, she politely informed them of her plans to earn money by working part time to pay her school fees. Her parents then agreed to pay for her education."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78d3c8b15c3c','ch_8115c7e6aac6','text','{"text": "Wishing always to study"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce7fafa2b543','ch_8115c7e6aac6','text','{"text": "‘a bit more’ and with her father slowly getting used to her urge for more education, Santosh passed the high school examinations and went to Jaipur."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_517424cc98be','ch_8115c7e6aac6','text','{"text": "She joined Maharani College and got a room in Kasturba Hostel. Santosh remembers, ‘Kasturba Hostel faced the Aravalli Hills. I used to watch villagers from my room, going up the hill and suddenly vanishing after a while. One day I decided to check it out myself. I found nobody except a few mountaineers. I asked if I could join them. To my pleasant surprise, they answered in the affirmative and motivated me to take to climbing.’"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e650cf7f0aec','ch_8115c7e6aac6','text','{"text": "Then there was no looking back for this determined young girl. She saved money and enrolled in a course at Uttarkashi’s Nehru Institute of Mountaineering."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ce20ea272ee4','ch_8115c7e6aac6','text','{"text": "‘My college semester in Jaipur was to end in April but it ended on the nineteenth of May. And I was supposed to be in Uttarkashi on the twenty-first. So, I did not go back home; instead, I headed straight for the training. I had to write a letter of apology to my father without whose permission I had got myself enrolled at Uttarkashi.’"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d28f3daa42e','ch_8115c7e6aac6','text','{"text": "Thereafter, Santosh went on an expedition every year. Her climbing skills matured rapidly. Also, she developed a remarkable resistance to cold and the altitude. Equipped with an iron will, physical endurance and an amazing mental toughness, she proved herself repeatedly. The culmination of her hard work and sincerity came in 1992, just four years after she had shyly asked the Aravalli mountaineers if she could join them."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ad1dc05ca56','ch_8115c7e6aac6','text','{"text": "At barely twenty years of age, Santosh Yadav scaled Mt Everest, becoming the youngest woman in the world to achieve the feat. If her climbing skills, physical fitness, and mental strength impressed her seniors, her concern for others and desire to work together with them found her a special place in the hearts of fellow climbers. During the 1992 Everest mission, Santosh Yadav provided special care to a climber who lay dying at the South Col. She was unfortunately unsuccessful in saving him."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c8c3d39ec2a8','ch_8115c7e6aac6','text','{"text": "However, she managed to save another climber, Mohan Singh, who would have met with the same fate had she not shared her oxygen with him. Within twelve months, Santosh found herself a member of an Indo-Nepalese Women’s Expedition that invited her to join them. She then scaled the Everest a second time, thus setting a record as the only woman to have scaled the Everest twice, and securing for herself and India a unique place in the annals of mountaineering."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e5e6ff06edca','ch_8115c7e6aac6','text','{"text": "In recognition of her achievements, the Indian government bestowed upon her one of the nation’s top honours, the Padmashri. Describing her feelings when she was literally"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b8f5dfadd1bc','ch_8115c7e6aac6','text','{"text": "‘on top of the world’, Santosh has said, ‘It took some time for the enormity of the moment to sink in..."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ad34723543a7','ch_8115c7e6aac6','text','{"text": "Then I unfurled the Indian tricolour and held it aloft on the roof of the world. The feeling is indescribable. The Indian flag was flying on top of the world. It was truly a spiritual moment. I felt proud as an Indian.’"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d9959ca10ff','ch_8115c7e6aac6','text','{"text": "Also a fervent environmentalist, Santosh collected and brought down 500 kilograms of garbage from the Himalayas."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58e6040fbf2c','ch_8115c7e6aac6','text','{"text": "Part II"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70adfe1df390','ch_8115c7e6aac6','text','{"text": "Maria Sharapova"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6d2581a507f','ch_8115c7e6aac6','text','{"text": "THERE is something disarming about Maria Sharapova, something at odds with her ready smile and glamorous attire. And that something in her lifted her on Monday, 22 August 2005 to the world number one position in women’s tennis. All this happened in almost no time."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_06ff2bf57582','ch_8115c7e6aac6','text','{"text": "Poised beyond her years, the Siberian born teenager took just four years as a professional to reach the pinnacle. However, the rapid ascent in a fiercely competitive world began nine years before with a level of sacrifice few children would be prepared to endure. Little Maria had not yet celebrated her tenth birthday when she was packed off to train in the United States. That trip to Florida with her father Yuri launched her on the path to success and stardom."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_834787c100c0','ch_8115c7e6aac6','text','{"text": "But it also required a heart-wrenching two-year separation from her mother Yelena. The latter was compelled to stay back in Siberia because of visa restrictions. The nine-year-old girl had already learnt an important lesson in life — that tennis excellence would only come at a price."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f141e9193c4a','ch_8115c7e6aac6','text','{"text": "‘I used to be so lonely,’ Maria Sharapova recalls."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_83a728d03c66','ch_8115c7e6aac6','text','{"text": "‘I missed my mother terribly. My father was working as much as he could to keep my tennis-training going. So, he couldn’t see me either."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd56f2ca4a41','ch_8115c7e6aac6','text','{"text": "‘Because I was so young, I used to go to bed at 8 p.m. The other tennis pupils would come in at 11 p.m. and wake me up and order me to tidy up the room and clean it."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1566bc980eb4','ch_8115c7e6aac6','text','{"text": "‘Instead of letting that depress me, I became more quietly determined and mentally tough. I learnt how to take care of myself. I never thought of quitting because I knew what I wanted. When you come from nothing and you have nothing, then it makes you very hungry and determined . .. I would have put up with much more humiliation and insults than that to steadfastly pursue my dream.’"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b191329d2da4','ch_8115c7e6aac6','text','{"text": "That toughness runs through Maria even today. It was the key to her bagging the women’s singles crown at Wimbledon in 2004 and to her meteoric rise to the world number one spot the following year. While her journey from the frozen plains of Siberia to the summit of women’s tennis has touched the hearts of tennis fans, for the youngster herself there appears to be no room for sentiment."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d5143fde962e','ch_8115c7e6aac6','text','{"text": "The straight looks and the answers she gives when asked about her ambition make it amply clear that she considers the sacrifices were worth it."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f0a39a382355','ch_8115c7e6aac6','text','{"text": "‘I am very, very competitive. I work hard at what I do. It’s my job.’"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd685e62ec5e','ch_8115c7e6aac6','text','{"text": "This is her mantra for success. Though Maria Sharapova speaks with a pronounced American accent, she proudly parades her Russian nationality. Clearing all doubts, she says, ‘I’m Russian. It’s true that the U.S. is a big part of my life. But I have Russian citizenship. My blood is totally Russian. I will play the Olympics for Russia if they want me.’"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_358e6262da2d','ch_8115c7e6aac6','text','{"text": "Like any number of teenaged sensations, Maria Sharapova lists fashion, singing and dancing as her hobbies. She loves reading the novels of Arthur Conan Doyle. Her fondness for sophisticated evening gowns appears at odds with her love of pancakes with chocolate spread and fizzy orange drinks. Maria Sharapova cannot be pigeon-holed or categorised. Her talent, unwavering desire to succeed and readiness to sacrifice have lifted her to the top of the world."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c6f8dc5002a','ch_8115c7e6aac6','text','{"text": "Few would grudge her the riches she is now reaping. This is what she has to say about her monetary gains from tennis:"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a25e1f581b0','ch_8115c7e6aac6','text','{"text": "‘Of course, money is a motivation. Tennis is a business and a sport, but the most important thing is to become number one in the world. That’s the dream that kept me going.’"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_916ee004281b','ch_8115c7e6aac6','text','{"text": "*********"}',39);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_6e8b46fa6ff0','bk_ncert_english','9-15-on-killing-a-tree','9.15 On Killing a Tree',NULL,'public',15,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d015a43105b3','ch_6e8b46fa6ff0','text','{"text": "It takes much time to kill a tree,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe57a9e11e01','ch_6e8b46fa6ff0','text','{"text": "Not a simple jab of the knife"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f144368a9420','ch_6e8b46fa6ff0','text','{"text": "Will do it. It has grown"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bbec567d0277','ch_6e8b46fa6ff0','text','{"text": "Slowly consuming the earth,"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5b6c59f72762','ch_6e8b46fa6ff0','text','{"text": "Rising out of it, feeding"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ab3ea86038ad','ch_6e8b46fa6ff0','text','{"text": "Upon its crust, absorbing"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f5c616e612b1','ch_6e8b46fa6ff0','text','{"text": "Years of sunlight, air, water,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0916c8c7a54b','ch_6e8b46fa6ff0','text','{"text": "And out of its leprous hide"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_abc57272b6a0','ch_6e8b46fa6ff0','text','{"text": "Sprouting leaves."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8f2eb272d42d','ch_6e8b46fa6ff0','text','{"text": "So hack and chop"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0543ee4ada0b','ch_6e8b46fa6ff0','text','{"text": "But this alone wont do it."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f2c2fbdf955','ch_6e8b46fa6ff0','text','{"text": "Not so much pain will do it."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a95b9a26c0b9','ch_6e8b46fa6ff0','text','{"text": "The bleeding bark will heal"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c9a207de60d','ch_6e8b46fa6ff0','text','{"text": "And from close to the ground"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7e119abaa2e5','ch_6e8b46fa6ff0','text','{"text": "Will rise curled green twigs,"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9ceb0166abb8','ch_6e8b46fa6ff0','text','{"text": "Miniature boughs"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89eeb323dbeb','ch_6e8b46fa6ff0','text','{"text": "Which if unchecked will expand again"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a31e0753e21d','ch_6e8b46fa6ff0','text','{"text": "To former size."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46253382c377','ch_6e8b46fa6ff0','text','{"text": "No,"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f01d4d37211','ch_6e8b46fa6ff0','text','{"text": "The root is to be pulled out —"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8b52758194d0','ch_6e8b46fa6ff0','text','{"text": "Out of the anchoring earth;"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9afd8611eb4d','ch_6e8b46fa6ff0','text','{"text": "It is to be roped, tied,"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92625a80e3e5','ch_6e8b46fa6ff0','text','{"text": "And pulled out — snapped out"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3d4417a516a2','ch_6e8b46fa6ff0','text','{"text": "Or pulled out entirely,"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fd4d634f12b8','ch_6e8b46fa6ff0','text','{"text": "Out from the earth-cave,"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dfdeed10bb74','ch_6e8b46fa6ff0','text','{"text": "And the strength of the tree exposed"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4777dd3f26b0','ch_6e8b46fa6ff0','text','{"text": "The source, white and wet,"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e2909f45113','ch_6e8b46fa6ff0','text','{"text": "The most sensitive, hidden"}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0024f6132776','ch_6e8b46fa6ff0','text','{"text": "For years inside the earth."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_329707cbe76a','ch_6e8b46fa6ff0','text','{"text": "Then the matter"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_230b12dca77c','ch_6e8b46fa6ff0','text','{"text": "Of scorching and choking"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eec06e324466','ch_6e8b46fa6ff0','text','{"text": "In sun and air,"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_74489d226ae7','ch_6e8b46fa6ff0','text','{"text": "Browning, hardening,"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e30159a1525','ch_6e8b46fa6ff0','text','{"text": "Twisting, withering,"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72f10b7bac7a','ch_6e8b46fa6ff0','text','{"text": "And then it is done."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_078f2fa19e0c','ch_6e8b46fa6ff0','heading','{"level": 2, "text": "Gieve Patel"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cc9ced3b900f','ch_6e8b46fa6ff0','text','{"text": "*********"}',37);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_57187408834b','bk_ncert_english','9-16-trees','9.16 Trees',NULL,'public',16,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec6117a7c4a2','ch_57187408834b','text','{"text": "I think that I shall never see"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7070fc25461','ch_57187408834b','text','{"text": "A poem lovely as a tree."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1cb359a9da3e','ch_57187408834b','text','{"text": "A tree whose hungry mouth is prest"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f2d43d12e60','ch_57187408834b','text','{"text": "Against the earth’s sweet flowing breast;"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_aa23e8dde11d','ch_57187408834b','text','{"text": "A tree that looks at God all day"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4973efa4151d','ch_57187408834b','text','{"text": "And lifts her leafy arms to pray;"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_114d09c8d164','ch_57187408834b','text','{"text": "A tree that may in summer wear"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a1def6c7ae51','ch_57187408834b','text','{"text": "A nest of robins in her hair;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_512c24987cd4','ch_57187408834b','text','{"text": "Upon whose bosom snow has lain;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_834569e28805','ch_57187408834b','text','{"text": "Who intimately lives with rain."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d03617b7c03','ch_57187408834b','text','{"text": "Poems are made by fools like me,"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c96f1a4b0af','ch_57187408834b','text','{"text": "But only God can make a tree."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_57d9799a3628','ch_57187408834b','heading','{"level": 2, "text": "Joyce Kilmer"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a786fda3fa90','ch_57187408834b','text','{"text": "*********"}',14);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_d5c67657ee57','bk_ncert_english','9-17-the-bond-of-love','9.17 The Bond of Love',NULL,'public',17,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c4e57f9faa8','ch_d5c67657ee57','text','{"text": "I WILL begin with Bruno, my wife’s pet sloth bear. I got him for her by accident. Two years ago we were passing through the sugarcane fields near Mysore. People were driving away the wild pigs from the fields by shooting at them. Some were shot and some escaped. We thought that everything was over when suddenly a black sloth bear came out panting in the hot sun."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_00c5fe1e1b4e','ch_d5c67657ee57','text','{"text": "Now I will not shoot a sloth bear wantonly but, unfortunately for the poor beast, one of my companions did not feel that way about it, and promptly shot the bear on the spot. As we watched the fallen animal we were surprised to see that the black fur on its back moved and left the prostrate body. Then we saw it was a baby bear that had been riding on its mother’s back when the sudden shot had killed her. The little creature ran around its prostrate parent making a pitiful noise."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f7ba16d029bb','ch_d5c67657ee57','text','{"text": "I ran up to it to attempt a capture. It scooted into the sugarcane field. Following it with my companions, I was at last able to grab it by the scruff of its neck while it snapped and tried to scratch me with its long, hooked claws. We put it in one of the gunny-bags we had brought and when I got back to Bangalore I duly presented it to my wife. She was delighted! She at once put a coloured ribbon around its neck, and after discovering the cub was a"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_070fcad2554a','ch_d5c67657ee57','text','{"text": "‘boy’ she christened it Bruno. Bruno soon took to drinking milk from a bottle. It was but a step further and within a very few days he started eating and drinking everything else. And everything is the right word, for he ate porridge made from any ingredients, vegetables, fruit, nuts, meat (especially pork), curry and rice regardless of condiments and chillies, bread, eggs, chocolates, sweets, pudding, ice-cream, etc., etc., etc."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b9d77a1af561','ch_d5c67657ee57','text','{"text": "As for drink:"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf7b5a248f25','ch_d5c67657ee57','text','{"text": "milk, tea, coffee, lime-juice, aerated water, buttermilk, beer, alcoholic liquor and, in fact, anything liquid. It all went down with relish. The bear became very attached to our two Alsatian dogs and to all the children of the tenants living in our bungalow. He was left quite free in his younger days and spent his time in playing, running into the kitchen and going to sleep in our beds. One day an accident befell him."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_97ef2c61c3e5','ch_d5c67657ee57','text','{"text": "I put down poison (barium carbonate) to kill the rats and mice that had got into my library. Bruno entered the library as he often did, and he ate some of the poison. Paralysis set in to the extent that he could not stand on his feet. But he dragged himself on his stumps to my wife, who called me. I guessed what had happened. Off I rushed in the car to the vet’s residence."}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a11cb07476c','ch_d5c67657ee57','text','{"text": "A case of poisoning! Tame Bear—barium carbonate—what to do? Out came his medical books, and a feverish reference to index began:"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b50b2d91ce19','ch_d5c67657ee57','text','{"text": "‘What poison did you say, sir?’"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05090ce84b9d','ch_d5c67657ee57','text','{"text": "‘Barium carbonate’."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_01821f5059cb','ch_d5c67657ee57','text','{"text": "‘Ah yes—B—Ba—Barium Salts—Ah! Barium carbonate! Symptoms— paralysis—treatment—injections of . .. Just a minute, sir. I’ll bring my syringe and the medicine.’"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f985dfdbda72','ch_d5c67657ee57','text','{"text": "A dash back to the car. Bruno still floundering about on his stumps, but clearly weakening rapidly; some vomiting, heavy breathing, with heaving flanks and gaping mouth. Hold him, everybody! In goes the hypodermic— Bruno squeals — 10 c.c. of the antidote enters his system without a drop being wasted. Ten minutes later:"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c5748ac1f0a9','ch_d5c67657ee57','text','{"text": "condition unchanged! Another 10 c.c. injected! Ten minutes later:"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_58770fd2c06b','ch_d5c67657ee57','text','{"text": "breathing less stertorous— Bruno can move his arms and legs a little although he cannot stand yet."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5741b2f042c6','ch_d5c67657ee57','text','{"text": "Thirty minutes later:"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_943b42f89318','ch_d5c67657ee57','text','{"text": "Bruno gets up and has a great feed! He looks at us disdainfully, as much as to say, ‘What’s barium carbonate to a big black bear like me?’ Bruno is still eating. Another time he found nearly one gallon of old engine oil which I had drained from the sump of the Studebaker and was keeping as a weapon against the inroads of termites. He promptly drank the lot. But it had no ill effects whatever. The months rolled on and Bruno had grown many times the size he was when he came."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f82c82519fca','ch_d5c67657ee57','text','{"text": "He had equalled the Alsatians in height and had even outgrown them. But was just as sweet, just as mischievous, just as playful. And he was very fond of us all. Above all, he loved my wife, and she loved him too! She had changed his name from Bruno, to Baba, a Hindustani word signifying"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_608c1475a549','ch_d5c67657ee57','text','{"text": "‘small boy’."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe8ecccd12e9','ch_d5c67657ee57','text','{"text": "And he could do a few tricks, too. At the command, ‘Baba, wrestle’, or"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b938e5d99017','ch_d5c67657ee57','text','{"text": "‘Baba, box,’ he vigorously tackled anyone who came forward for a rough and tumble. Give him a stick and say"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_10aca8077a45','ch_d5c67657ee57','text','{"text": "‘Baba, hold gun’, and he pointed the stick at you."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_888e50cf5975','ch_d5c67657ee57','text','{"text": "Ask him, ‘Baba, where’s baby?’ and he immediately produced and cradled affectionately a stump of wood which he had carefully concealed in his straw bed. But because of the tenants’ children, poor Bruno, or Baba, had to be kept chained most of the time. Then my son and I advised my wife, and friends advised her too, to give Baba to the zoo at Mysore. He was getting too big to keep at home. After some weeks of such advice she at last consented."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8a7b8017b093','ch_d5c67657ee57','text','{"text": "Hastily, and before she could change her mind, a letter was written to the curator of the zoo. Did he want a tame bear for his collection? He replied, ‘Yes’. The zoo sent a cage from Mysore in a lorry, a distance of eighty-seven miles, and Baba was packed off. We all missed him greatly; but in a sense we were relieved. My wife was inconsolable. She wept and fretted. For the first few days she would not eat a thing. Then she wrote a number of letters to the curator."}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bce3d5cc7d5a','ch_d5c67657ee57','text','{"text": "How was Baba? Back came the replies, ‘Well, but fretting; he refuses food too.’"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_304453853041','ch_d5c67657ee57','text','{"text": "After that, friends visiting Mysore were begged to make a point of going to the zoo and seeing how Baba was getting along. They reported that he was well but looked very thin and sad. All the keepers at the zoo said he was fretting. For three months I managed to restrain my wife from visiting Mysore. Then she said one day, ‘I must see Baba. Either you take me by car; or I will go myself by bus or train.’"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c74853d70b7c','ch_d5c67657ee57','text','{"text": "So I took her by car. Friends had conjectured that the bear would not recognise her. I had thought so too. But while she was yet some yards from his cage Baba saw her and recognised her. He howled with happiness. She ran up to him, petted him through the bars, and he stood on his head in delight. For the next three hours she would not leave that cage. She gave him tea, lemonade, cakes, ice-cream and what not. Then"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5dfbcc7ad72f','ch_d5c67657ee57','text','{"text": "‘closing time’ came and we had to leave."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3f58573730b3','ch_d5c67657ee57','text','{"text": "My wife cried bitterly; Baba cried bitterly; even the hardened curator and the keepers felt depressed. As for me, I had reconciled myself to what I knew was going to happen next."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0f7b9336dace','ch_d5c67657ee57','text','{"text": "‘Oh please, sir,’ she asked the curator, ‘may I have my Baba back’? Hesitantly, he answered, ‘Madam, he belongs to the zoo and is Government property now."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_92259658923f','ch_d5c67657ee57','text','{"text": "I cannot give away Government property. But if my boss, the superintendent at Bangalore agrees, certainly you may have him back.’"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e85b4da376c2','ch_d5c67657ee57','text','{"text": "There followed the return journey to Bangalore and a visit to the superintendent’s bungalow. A tearful pleading:"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a0fd0f6b1d78','ch_d5c67657ee57','text','{"text": "‘Baba and I are both fretting for each other. Will you please give him back to me?’ He was a kind-hearted man and consented. Not only that, but he wrote to the curator telling him to lend us a cage for transporting the bear to Bangalore. Back we went to Mysore again, armed with the superintendent’s letter. Baba was driven into a small cage and hoisted on top of the car; the cage was tied securely, and a slow and careful return journey to Bangalore was accomplished."}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd55064212e3','ch_d5c67657ee57','text','{"text": "Once home, a squad of coolies were engaged for special work in our compound. An island was made for Baba. It was twenty feet long and fifteen feet wide, and was surrounded by a dry pit, or moat, six feet wide and seven feet deep. A wooden box that once housed fowls was brought and put on the island for Baba to sleep in at night. Straw was placed inside to keep him warm, and his"}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3b199efde06','ch_d5c67657ee57','text','{"text": "‘baby’, the gnarled stump, along with his"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_375e4e8c1aeb','ch_d5c67657ee57','text','{"text": "‘gun’, the piece of bamboo, both of which had been sentimentally preserved since he had been sent away to the zoo, were put back for him to play with. In a few days the coolies hoisted the cage on to the island and Baba was released. He was delighted; standing on his hindlegs, he pointed his"}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ae0791296dc','ch_d5c67657ee57','text','{"text": "‘gun’ and cradled his"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2d04de962ac','ch_d5c67657ee57','text','{"text": "‘baby’. My wife spent hours sitting on a chair there while he sat on her lap. He was fifteen months old and pretty heavy too! The way my wife reaches the island and leaves it is interesting. I have tied a rope to the overhanging branch of a mango tree with a loop at its end. Putting one foot in the loop, she kicks off with the other, to bridge the six-foot gap that constitutes the width of the surrounding pit. The return journey is made the same way."}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89146e77371c','ch_d5c67657ee57','text','{"text": "But who can say now that a sloth bear has no sense of affection, no memory and no individual characteristics?"}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e859be097d6','ch_d5c67657ee57','heading','{"level": 2, "text": "Kenneth Anderson"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_deb4a94618c4','ch_d5c67657ee57','text','{"text": "Report comes in support of snake charmers"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1dfcd50972f0','ch_d5c67657ee57','text','{"text": "By Our Staff Reporter NEW D ELHI, JUNE 15. Over 30 years after the introduction of the Wildlife Protection Act (WPA) that banned the catching of snakes in India, a small community of snake charmers continues to practise the trade catching over 400,000 snakes every year — which ultimately die — in defiance of the law. A report based on new research by the Wildlife Trust of India (WTI), however, has strongly recommended that the traditional knowledge of the snake charmers and skills be now utilised for education and medicine by setting up sapera centres. This is mainly because the community has virtually no access to land, education or employment opportunities. They are dependent on snake charming to earn a livelihood. They trade around as vendors of traditional medicine, snake catchers and musicians. Ignorance about the law is quite common. The report entitled ‘Biodiversity, Livelihoods and the Law: The Case of the Jogi-Nath Snake Charmers of India’ based on path-breaking research was formally released by the Inspector General of Forests, V.K. Bahuguna, along with a presentation by members of the sapera community in the Capital on Monday. “Despite thirty years of the law being in existence, over 70 per cent of the Jogi-Naths are still dependent on snake charming to earn a livelihood. Ignorance about the law was quite common. None of them own land, even though they would like to,’’ said Bahar Dutt, who led this research. Notably, most of those practising the trade in the current generation are all under 35 years of age. Trapping occurs throughout the year and during their travels, though this activity increases during the monsoons. According to the data, each family on an average collects at least seven snakes. Most snakes were force-fed and snake husbandry methods and health were found to be poor. “The snake charmers community council imposes a heavy fine on a person if the snake dies in his custody as it is considered an extremely bad omen. As a result, the snakes are released when the charmers realise that their condition is deteriorating,’’ said Dutt. Their ambition to showcase the reptiles and earn money was not fulfilled, as they flouted four WPA provisions, for illegally possessing the animals, not feeding them properly, causing injuries by extracting teeth unscientifically and killing snakes for the valuable snake parts and bones. Their offence generally invites imprisonment for three to seven years and a fine up to Rs 25,000 in each case. “On the positive side researchers found that the snake charmers possess a unique ability to handle venomous snakes with a tremendous knowledge of the different species and their behaviour. They are also called by local farmers to retrieve snakes, who would otherwise just kill them, from agricultural fields or human inhabited areas,’’ she said."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2b7754581929','ch_d5c67657ee57','text','{"text": "*********"}',42);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_06ba04862de4','bk_ncert_english','9-18-the-snake-trying','9.18 The Snake Trying',NULL,'public',18,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_548c90f2eaf4','ch_06ba04862de4','text','{"text": "The snake trying"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c59d5bec85af','ch_06ba04862de4','text','{"text": "to escape the pursuing stick,"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f2e644e99605','ch_06ba04862de4','text','{"text": "with sudden curvings of thin"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_521d53c7d6d3','ch_06ba04862de4','text','{"text": "long body. How beautiful"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e33993a394d3','ch_06ba04862de4','text','{"text": "and graceful are his shapes!"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_da53c807d9d9','ch_06ba04862de4','text','{"text": "He glides through the water away"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_653807d77c48','ch_06ba04862de4','text','{"text": "from the stroke. O let him go"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6d2bd811e9d8','ch_06ba04862de4','text','{"text": "over the water"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_849b19b3278f','ch_06ba04862de4','text','{"text": "into the reeds to hide"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d6614d708a2','ch_06ba04862de4','text','{"text": "without hurt. Small and green"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_05d8ef05d32a','ch_06ba04862de4','text','{"text": "he is harmless even to children."}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8ef3b06858d2','ch_06ba04862de4','text','{"text": "Along the sand"}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dcab61ebebfb','ch_06ba04862de4','text','{"text": "he lay until observed"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_89dc9397f1b8','ch_06ba04862de4','text','{"text": "and chased away, and now"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b97cd6b24354','ch_06ba04862de4','text','{"text": "he vanishes in the ripples"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9602b3cb82c1','ch_06ba04862de4','text','{"text": "among the green slim reeds."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b2eb532c1fab','ch_06ba04862de4','heading','{"level": 2, "text": "W.W.E. Ross"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3595d26dc854','ch_06ba04862de4','text','{"text": "Green Snake"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b206dc9943e5','ch_06ba04862de4','text','{"text": "Early morning, the day before yesterday,"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4f89b20f5f24','ch_06ba04862de4','text','{"text": "under a slab of stone,"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7c1255eae920','ch_06ba04862de4','text','{"text": "in a crack,"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_847df7f9f9e0','ch_06ba04862de4','text','{"text": "eyes glittering,"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f4059127ed5a','ch_06ba04862de4','text','{"text": "forked tongue licking and flashing,"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_07bd4b501ece','ch_06ba04862de4','text','{"text": "a frog swelling his belly,"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0125dfec2111','ch_06ba04862de4','text','{"text": "he lay there quietly:"}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e2b6e7e4ac9','ch_06ba04862de4','text','{"text": "a baby snake, two hands long,"}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7035158f8732','ch_06ba04862de4','text','{"text": "a green snake."}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a6d5d47bebd','ch_06ba04862de4','text','{"text": "“Poor thing. It’s a green snake. Still a baby."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ccbddcbde770','ch_06ba04862de4','text','{"text": "What harm can it do?” I said."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd5692b0bffa','ch_06ba04862de4','text','{"text": "My father replied,"}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b680d197348f','ch_06ba04862de4','text','{"text": "“A snake’s a snake.”"}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4095a9876ec','ch_06ba04862de4','text','{"text": "And mother,"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4898d9491bc8','ch_06ba04862de4','text','{"text": "“That’s where everyone walks."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_007f13f3ec83','ch_06ba04862de4','text','{"text": "We don’t need trouble. Kill it.”"}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_77e6d5bba90f','ch_06ba04862de4','text','{"text": "“I can’t,” I said."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4ac6088631e0','ch_06ba04862de4','text','{"text": "Father struck him with a piece of firewood,"}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_079b23a44106','ch_06ba04862de4','text','{"text": "chased him outside,"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fcc2a142aae4','ch_06ba04862de4','text','{"text": "and killed him flat."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3b0d1cb2534f','ch_06ba04862de4','heading','{"level": 2, "text": "B.R.Lakshman Rao"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_84cffef1cb3f','ch_06ba04862de4','text','{"text": "[translated by A.K. Ramanujan]"}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d8f33cc61430','ch_06ba04862de4','text','{"text": "*********"}',41);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_8e79b4f11388','bk_ncert_english','9-19-kathmandu','9.19 Kathmandu',NULL,'public',19,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2c5f71a713e7','ch_8e79b4f11388','text','{"text": "I GET a cheap room in the centre of town and sleep for hours. The next morning, with Mr Shah’s son and nephew, I visit the two temples in Kathmandu that are most sacred to Hindus and Buddhists. At Pashupatinath (outside which a sign proclaims"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_66adb2b030ee','ch_8e79b4f11388','text','{"text": "‘Entrance for the Hindus only’) there is an atmosphere of"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ec9396073676','ch_8e79b4f11388','text','{"text": "‘febrile confusion’."}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_21203b3625c7','ch_8e79b4f11388','text','{"text": "Priests, hawkers, devotees, tourists, cows, monkeys, pigeons and dogs roam through the grounds. We offer a few flowers. There are so many worshippers that some people trying to get the priest’s attention are elbowed aside by others pushing their way to the front. A princess of the Nepalese royal house appears; everyone bows and makes way. By the main gate, a party of saffron-clad Westerners struggle for permission to enter. The policeman is not convinced that they are"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b965283cde20','ch_8e79b4f11388','text','{"text": "‘the Hindus’ (only Hindus are allowed to enter the temple)."}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ee6a5195ec67','ch_8e79b4f11388','text','{"text": "A fight breaks out between two monkeys. One chases the other, who jumps onto a shivalinga, then runs screaming around the temples and down to the river, the holy Bagmati. that flows below. A corpse is being cremated on its banks; washerwomen are at their work and children bathe. From a balcony a basket of flowers and leaves, old offerings now wilted, is dropped into the river. A small shrine half protrudes from the stone platform on the river bank."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d3a0db499118','ch_8e79b4f11388','text','{"text": "When it emerges fully, the goddess inside will escape, and the evil period of the Kaliyug will end on earth. At the Baudhnath stupa, the Buddhist shrine of Kathmandu, there is, in contrast, a sense of stillness. Its immense white dome is ringed by a road. Small shops stand on its outer edge:"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_606648bdd9d6','ch_8e79b4f11388','text','{"text": "many of these are owned by Tibetan immigrants; felt bags, Tibetan prints and silver jewellery can be bought here. There are no crowds:"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_08b3a0ff556d','ch_8e79b4f11388','text','{"text": "this is a haven of quietness in the busy streets around."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ae82cfb0a0e','ch_8e79b4f11388','text','{"text": "Kathmandu is vivid, mercenary, religious, with small shrines to flower-adorned deities along the narrowest and busiest streets; with fruit sellers, flute sellers, hawkers of postcards; shops selling Western cosmetics, film rolls and chocolate; or copper utensils and Nepalese antiques. Film songs blare out from the radios, car horns sound, bicycle bells ring, stray cows low questioningly at motorcycles, vendors shout out their wares."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b393fbd75f6a','ch_8e79b4f11388','text','{"text": "I indulge myself mindlessly:"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28806b5c3234','ch_8e79b4f11388','text','{"text": "buy a bar of marzipan, a cornon- the-cob roasted in a charcoal brazier on the pavement (rubbed with salt, chilli powder and lemon); a couple of love story comics, and even a Reader’s Digest. All this I wash down with Coca Cola and a nauseating orange drink, and feel much the better for it. I consider what route I should take back home."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d800d40c5d8','ch_8e79b4f11388','text','{"text": "If I were propelled by enthusiasm for travel per se, I would go by bus and train to Patna, then sail up the Ganges past Benaras to Allahabad, then up the Yamuna, past Agra to Delhi. But I am too exhausted and homesick; today is the last day of August. Go home, I tell myself:"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c20571859ae','ch_8e79b4f11388','text','{"text": "move directly towards home. I enter a Nepal Airlines office and buy a ticket for tomorrow’s flight. I look at the flute seller standing in a corner of the square near the hotel."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0bb6aaea49e6','ch_8e79b4f11388','text','{"text": "In his hand is a pole with an attachment at the top from which fifty or sixty bansuris protrude in all directions, like the quills of a porcupine. They are of bamboo:"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3404107edfcc','ch_8e79b4f11388','text','{"text": "there are cross-flutes and recorders. From time to time he stands the pole on the ground, selects a flute and plays for a few minutes. The sound rises clearly above the noise of the traffic and the hawkers’ cries. He plays slowly, meditatively, without excessive display. He does not shout out his wares."}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cd106b9535f9','ch_8e79b4f11388','text','{"text": "Occasionally he makes a sale, but in a curiously offhanded way as if this were incidental to his enterprise. Sometimes he breaks off playing to talk to the fruit seller. I imagine that this has been the pattern of his life for years. I find it difficult to tear myself away from the square. Flute music always does this to me:"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e59c6e479d66','ch_8e79b4f11388','text','{"text": "it is at once the most universal and most particular of sounds."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3efc85739982','ch_8e79b4f11388','text','{"text": "There is no culture that does not have its flute — the reed neh, the recorder, the Japanese shakuhachi, the deep bansuri of Hindustani classical music, the clear or breathy flutes of South America, the high-pitched Chinese flutes. Each has its specific fingering and compass. It weaves its own associations. Yet to hear any flute is, it seems to me, to be drawn into the commonality of all mankind, to be moved by music closest in its phrases and sentences to the human voice."}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0e6819482135','ch_8e79b4f11388','text','{"text": "Its motive force too is living breath:"}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_6aae071ab1d0','ch_8e79b4f11388','text','{"text": "it too needs to pause and breathe before it can go on. That I can be so affected by a few familiar phrases on the bansuri, surprises me at first, for on the previous occasions that I have returned home after a long absence abroad, I have hardly noticed such details, and certainly have not invested them with the significance I now do."}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0412f179d138','ch_8e79b4f11388','heading','{"level": 2, "text": "Vikram Seth"}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11f390e8b25b','ch_8e79b4f11388','text','{"text": "[an extract from Heaven Lake]"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ef913c1153bc','ch_8e79b4f11388','text','{"text": "*********"}',24);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_b8bb8530f3e6','bk_ncert_english','9-20-a-slumber-did-my-spirit-seal','9.20 A Slumber Did My Spirit Seal',NULL,'public',20,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cca663bcfc4c','ch_b8bb8530f3e6','text','{"text": "A slumber did my spirit seal—"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f8936e96b2b','ch_b8bb8530f3e6','text','{"text": "I had no human fears."}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_18760e8bab64','ch_b8bb8530f3e6','text','{"text": "She seemed a thing that could not feel"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bf9242f78fe7','ch_b8bb8530f3e6','text','{"text": "The touch of earthly years."}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7839543b3de9','ch_b8bb8530f3e6','text','{"text": "No motion has she now, no force—"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_911a438f1c68','ch_b8bb8530f3e6','text','{"text": "She neither hears nor sees,"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e72d8b2f83b6','ch_b8bb8530f3e6','text','{"text": "Rolled round in earth’s diurnal course"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f886e8d5a1b7','ch_b8bb8530f3e6','text','{"text": "With rocks and stones and trees."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_114fd9cc78ae','ch_b8bb8530f3e6','heading','{"level": 2, "text": "William Wordsworth"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_47694d6e6caa','ch_b8bb8530f3e6','text','{"text": "*********"}',10);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_5c4a094b4235','bk_ncert_english','9-21-fear-no-more','9.21 Fear No More',NULL,'public',21,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d0d47be31927','ch_5c4a094b4235','text','{"text": "Fear no more the heat o’ the sun,"}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8aaac7c87396','ch_5c4a094b4235','text','{"text": "Nor the furious winter’s rages;"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_279b6d358069','ch_5c4a094b4235','text','{"text": "Thou thy worldly task hast done,"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8989ed8ed9a6','ch_5c4a094b4235','text','{"text": "Home art gone, and ta’en thy wages:"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_45a4e5ae5fe0','ch_5c4a094b4235','text','{"text": "Golden lads and girls all must,"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0bc0d9e87906','ch_5c4a094b4235','text','{"text": "As chimney-sweepers, come to dust."}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cbfdefe170c3','ch_5c4a094b4235','text','{"text": "Fear no more the frown o’ the great,"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_748d33109808','ch_5c4a094b4235','text','{"text": "Thou art past the tyrant’s stroke;"}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4e0676eaa3b7','ch_5c4a094b4235','text','{"text": "Care no more to clothe and eat;"}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5eb3725a93cd','ch_5c4a094b4235','text','{"text": "To thee the reed is as the oak:"}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0c7c8bc6b074','ch_5c4a094b4235','text','{"text": "The sceptre, learning, physic, must"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2d52f4e4539e','ch_5c4a094b4235','text','{"text": "All follow this, and come to dust."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dc8dab3ba195','ch_5c4a094b4235','text','{"text": "Fear no more the lightning-flash,"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d05b5d0d986','ch_5c4a094b4235','text','{"text": "Nor the all-dreaded thunder-stone;"}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9f54e71aeb9d','ch_5c4a094b4235','text','{"text": "Fear not slander, censure rash;"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d97e64daf4b3','ch_5c4a094b4235','text','{"text": "Thou hast finished joy and moan:"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c67132850159','ch_5c4a094b4235','text','{"text": "All lovers young, all lovers must"}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1c5ae264f0ad','ch_5c4a094b4235','text','{"text": "Consign to thee, and come to dust."}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_de2d6a529948','ch_5c4a094b4235','heading','{"level": 2, "text": "William Shakespeare"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c29b782dfe14','ch_5c4a094b4235','text','{"text": "*********"}',20);
INSERT INTO chapters (id,book_id,slug,title,summary,access_level,sort_order,is_published,updated_at) VALUES ('ch_e13b8f0edb1b','bk_ncert_english','9-22-if-i-were-you','9. 22  If I Were You',NULL,'public',22,1,datetime('now'));
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_eb7aab8c5ebc','ch_e13b8f0edb1b','text','{"text": "SCENE: A small cottage interior. There is an entrance back right (which may be curtained). Another door to the left must be a practical door. The furniture is simple, consisting of a small table towards the left, a chair or two, and a divan rather upstage on the right. On the table is a telephone."}',1);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_615dfac4e81a','ch_e13b8f0edb1b','text','{"text": "When the curtain rises Gerrard is standing by the table making a phone call. He is of medium height, and wearing horn-rimmed glasses . . . He is dressed in a lounge suit and a great coat. His voice is cultured.)"}',2);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_37f2565bbf6c','ch_e13b8f0edb1b','text','{"text": "GERRARD : ... Well, tell him to phone up directly. I must know ... Yes, I expect I’ll still be here, but you mustn’t count on that ... In about ten minutes’ time. Right-ho. Goodbye. (He puts down the phone and goes to the divan on the left, where there is a travelling bag, and starts packing. Whilst he is thus engaged, another man, similar in build to Gerrard enters from the right silently — revolver in hand. He is flashily dressed in an overcoat and a soft hat. He bumps accidentally against the table, and at the sound Gerrard turns quickly.)"}',3);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_94fde64e928d','ch_e13b8f0edb1b','text','{"text": "GERRARD : (pleasantly) Why, this is a surprise, Mr— er—"}',4);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_36551ff296e1','ch_e13b8f0edb1b','text','{"text": "INTRUDER : I’m glad you’re pleased to see me. I don’t think you’ll be pleased for long. Put those paws up!"}',5);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_87e23636b723','ch_e13b8f0edb1b','text','{"text": "GERRARD : This is all very melodramatic, not very original, perhaps, but…"}',6);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3a3bac0d4744','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Trying to be calm and —er—"}',7);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_38ab58ad3354','ch_e13b8f0edb1b','text','{"text": "GERRARD : ‘Nonchalant’ is your word, I think."}',8);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d83fa3aba7ae','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Thanks a lot. You’ll soon stop being smart. I’ll make you crawl. I want to know a few things, see."}',9);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_baae3f88ddec','ch_e13b8f0edb1b','text','{"text": "GERRARD : Anything you like. I know all the answers. But before we begin I should like to change my position; you may be comfortable, but I am not."}',10);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5c0f22f536d2','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Sit down there, and no funny business. (Motions to a chair, and seats himself on the divan by the bag.) Now then, we’ll have a nice little talk about yourself!"}',11);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_074eb2db559f','ch_e13b8f0edb1b','text','{"text": "GERRARD : At last a sympathetic audience! I’ll tell you the story of my life. How as a child I was stolen by the gypsies, and why at the age of thirty-two, I find myself in my lonely Essex cottage, how ..."}',12);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ed74514707fa','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Keep it to yourself, and just answer my questions. You live here alone? Well, do you?"}',13);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_671cb5a289be','ch_e13b8f0edb1b','text','{"text": "GERRARD : I’m sorry. I thought you were telling me, not asking me. A question of inflection; your voice is unfamiliar."}',14);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bfd06714c82b','ch_e13b8f0edb1b','text','{"text": "INTRUDER : (with emphasis) Do you live here alone?"}',15);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_14531054444b','ch_e13b8f0edb1b','text','{"text": "GERRARD : And if I don’t answer?"}',16);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d153322134ea','ch_e13b8f0edb1b','text','{"text": "INTRUDER : You’ve got enough sense not to want to get hurt."}',17);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_018546154c37','ch_e13b8f0edb1b','text','{"text": "GERRARD : I think good sense is shown more in the ability to avoid pain than in the mere desire to do so. What do you think, Mr— er—"}',18);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2e5bc42e719','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Never mind my name. I like yours better, Mr Gerrard. What are your Christian names?"}',19);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9773a2ba1ea6','ch_e13b8f0edb1b','text','{"text": "GERRARD : Vincent Charles."}',20);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4d5d20f7222a','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Do you run a car?"}',21);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_fe2520ea0cec','ch_e13b8f0edb1b','text','{"text": "GERRARD : No."}',22);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f3fbd60fac67','ch_e13b8f0edb1b','text','{"text": "INTRUDER : That’s a lie. You’re not dealing with a fool. I’m as smart as you and smarter, and I know you run a car. Better be careful, wise guy!"}',23);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a2bb487be489','ch_e13b8f0edb1b','text','{"text": "GERRARD : Are you American, or is that merely a clever imitation?"}',24);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_39ee2d3bd801','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Listen, this gun’s no toy. I can hurt you without killing you, and still get my answers."}',25);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_637dd73f9790','ch_e13b8f0edb1b','text','{"text": "GERRARD : Of course, if you put it like that, I’ll be glad to assist you. I do possess a car, and it’s in the garage round the corner."}',26);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e0cdd1cc77fa','ch_e13b8f0edb1b','text','{"text": "INTRUDER : That’s better. Do people often come out here?"}',27);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_504712cb07d4','ch_e13b8f0edb1b','text','{"text": "GERRARD : Very rarely. Surprisingly few people take the trouble to visit me. There’s the baker and the greengrocer, of course; and then there’s the milkman — quite charming, but no one so interesting as yourself."}',28);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_734b68645364','ch_e13b8f0edb1b','text','{"text": "INTRUDER : I happen to know that you never see tradespeople."}',29);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_507a4e4b927a','ch_e13b8f0edb1b','text','{"text": "GERRARD : You seem to have taken a considerable amount of trouble. Since you know so much about me, won’t you say something about yourself? You have been so modest. INTRUDER : I could tell you plenty. You think you’re smart, but I’m the top of the class round here. I’ve got brains and I use them. That’s how I’ve got where I have."}',30);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_61ace6639372','ch_e13b8f0edb1b','text','{"text": "GERRARD : And where precisely have you got? It didn’t require a great brain to break into my little cottage. INTRUDER : When you know why I’ve broken into your little cottage, you’ll be surprised, and it won’t be a pleasant surprise."}',31);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3c6d5ff16fef','ch_e13b8f0edb1b','text','{"text": "GERRARD : With you figuring so largely in it, that is understandable. By the way, what particular line of crime do you embrace, or aren’t you a specialist?"}',32);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b168ecd306a3','ch_e13b8f0edb1b','text','{"text": "INTRUDER : My speciality’s jewel robbery. Your car will do me a treat. It’s certainly a dandy bus."}',33);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c7ece99d339a','ch_e13b8f0edb1b','text','{"text": "GERRARD : I’m afraid jewels are few and far between in the wilds of Essex."}',34);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ea501fc3992e','ch_e13b8f0edb1b','text','{"text": "INTRUDER : So are the cops. I can retire here nicely for a little while."}',35);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_78d9d261b62e','ch_e13b8f0edb1b','text','{"text": "GERRARD : You mean to live with me? A trifle sudden isn’t it; you’ve not been invited. INTRUDER : You won’t be here long; so I didn’t trouble to ask."}',36);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2e00fd2efb24','ch_e13b8f0edb1b','text','{"text": "GERRARD : What do you mean?"}',37);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_70eeff967a26','ch_e13b8f0edb1b','text','{"text": "INTRUDER : This is your big surprise. I’m going to kill you."}',38);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23003a213f75','ch_e13b8f0edb1b','text','{"text": "GERRARD : A little harsh, isn’t it?"}',39);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d50800f87898','ch_e13b8f0edb1b','text','{"text": "INTRUDER : (with heavy sarcasm) Yeah, I’ll be sorry to do it. I’ve taken a fancy to you, but it’s just got to be done."}',40);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_b1fffb470548','ch_e13b8f0edb1b','text','{"text": "GERRARD : Why add murder to your other crimes? It’s a grave step you’re taking."}',41);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_3e24930a9382','ch_e13b8f0edb1b','text','{"text": "INTRUDER : I’m not taking it for fun. I’ve been hunted long enough. I’m wanted for murder already, and they can’t hang me twice."}',42);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_a4fd1926075d','ch_e13b8f0edb1b','text','{"text": "GERRARD : You’re planning a gratuitous double, so to speak. Admitted you’ve nothing to lose, but what have you to gain?"}',43);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_860a46bb8ba6','ch_e13b8f0edb1b','text','{"text": "INTRUDER : I’ve got freedom to gain. As for myself, I’m a poor hunted rat. As Vincent Charles Gerrard I’m free to go places and do nothing. I can eat well and sleep and without having to be ready to beat it at the sight of a cop."}',44);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1f119c68f8ce','ch_e13b8f0edb1b','text','{"text": "GERRARD : In most melodramas the villain is foolish enough to delay his killing long enough to be frustrated. You are much luckier."}',45);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_28ac13ce8efb','ch_e13b8f0edb1b','text','{"text": "INTRUDER : I’m O.K. I’ve got a reason for everything. I’m going to be Vincent Charles Gerrard, see. I’ve got to know what he talks like. Now I know. That posh stuff comes easy. This is Mr V.C. Gerrard speaking. (Pantomime of phoning, in imitation cultured voice.) And that’s not all. (He stands up.) Get up a minute (Gerrard stands.) Now take a look at me."}',46);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_dd5ff0ce7739','ch_e13b8f0edb1b','text','{"text": "GERRARD : You’re not particularly decorative."}',47);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_0a0d5b81532b','ch_e13b8f0edb1b','text','{"text": "INTRUDER : No! Well, that goes for you, too. I’ve only got to wear specs and I’ll be enough like you to get away with it."}',48);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_2fdbb10e8e4b','ch_e13b8f0edb1b','text','{"text": "GERRARD : What about your clothes? They’ll let you down if you’re not careful."}',49);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_11775e16b0ca','ch_e13b8f0edb1b','text','{"text": "INTRUDER : That’ll be all right. Yours will fit me fine."}',50);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5d48b99a65a8','ch_e13b8f0edb1b','text','{"text": "GERRARD : That is extremely interesting, but you seem to miss the point of my remark. I said, you were luckier than most melodramatic villains. It was not a tribute to your intelligence. You won’t kill me for a very good reason."}',51);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_e01108bdb603','ch_e13b8f0edb1b','text','{"text": "INTRUDER : So that’s what you think."}',52);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5e8521713c12','ch_e13b8f0edb1b','text','{"text": "GERRARD : You’ll let me go, and thank God you didn’t shoot sooner."}',53);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d6c54658a68a','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Come on. What’s on your mind! Better be quick. This conversation bores me."}',54);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_048868aa3cc9','ch_e13b8f0edb1b','text','{"text": "GERRARD : Your idea is to elude the police by killing me and taking on my identity?"}',55);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_432f4c81894d','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Yes, I like the idea."}',56);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_f5cc31856b66','ch_e13b8f0edb1b','text','{"text": "GERRARD : But are you sure it’s going to help you?"}',57);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_48ca7d404c7e','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Now listen here. I’ve got this all planned. I did a job in town. Things went wrong and I killed a cop. Since then I’ve done nothing but dodge."}',58);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_c6b9c285699f','ch_e13b8f0edb1b','text','{"text": "GERRARD : And this is where dodging has brought you?"}',59);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_46087d9d24a4','ch_e13b8f0edb1b','text','{"text": "INTRUDER : It brought me to Aylesbury. That’s where I saw you in the car. Two other people saw you and started to talk. I listened. It looks like you’re a bit queer — kind of a mystery man."}',60);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_69138de36d60','ch_e13b8f0edb1b','text','{"text": "GERRARD : A mystery which I propose to explain."}',61);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_cbc5848e7a7c','ch_e13b8f0edb1b','text','{"text": "INTRUDER : (disregarding him) You phone your orders and sometimes you go away suddenly and come back just the same. Those are just the things I want to do. Hearing about you was one of my luckiest breaks."}',62);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_23bf5e25e15e','ch_e13b8f0edb1b','text','{"text": "GERRARD : Apparently you haven’t the intelligence to ask why I am invested in this cloak of mystery."}',63);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7898bc70d352','ch_e13b8f0edb1b','text','{"text": "INTRUDER : (preparing to shoot) As I said before, this conversation bores me."}',64);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_d7f5c2611ea7','ch_e13b8f0edb1b','text','{"text": "GERRARD : Don’t be a fool. If you shoot, you’ll hang for sure. If not as yourself, then as Vincent Charles Gerrard."}',65);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bff89cc50835','ch_e13b8f0edb1b','text','{"text": "INTRUDER : What is this?"}',66);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_5f602c391e3f','ch_e13b8f0edb1b','text','{"text": "GERRARD : This is your big surprise. I said you wouldn’t kill me and I was right. Why do you think I am here today and gone tomorrow, never see tradespeople? You say my habits would suit you. You are a crook. Do you think I am a Sunday-school teacher? The game’s up as far as I’m concerned. Things went wrong with me. I said it with bullets and got away. Unfortunately they got one of my men, and found things the fool should have burnt. Tonight I’m expecting trouble. My bag’s packed ready to clear off. There it is."}',67);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_7ecf28d06670','ch_e13b8f0edb1b','text','{"text": "INTRUDER : It’s a bag all right and this is a gun all right. What’s all this?"}',68);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_72e86ad09453','ch_e13b8f0edb1b','text','{"text": "GERRARD : That’s a disguise outfit; false moustaches and what not. Now do you believe me? INTRUDER : (musingly) I don’t know."}',69);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_9dbad177818e','ch_e13b8f0edb1b','text','{"text": "GERRARD : For God’s sake clear that muddled head of yours and let’s go. Come with me in the car. I can use you. If you find it’s a frame, you’ve got me in the car, and you’ve still got your gun."}',70);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_bffd4045e81c','ch_e13b8f0edb1b','text','{"text": "INTRUDER : May be you’re right."}',71);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_55fde2015e04','ch_e13b8f0edb1b','text','{"text": "GERRARD : Then don’t waste time. (Goes and picks up hat and bag.)"}',72);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_1b991486892a','ch_e13b8f0edb1b','text','{"text": "INTRUDER : Careful, boss, I’m watching you."}',73);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_96646e7eea41','ch_e13b8f0edb1b','text','{"text": "GERRARD : I have got a man posted on the main road. He’ll ring up if he sees the police, but I don’t want to leave ... (telephone bell rings) Come on! They’re after us. Through here straight to the garage."}',74);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_98a4f4503a3f','ch_e13b8f0edb1b','text','{"text": "INTRUDER : How do I know that you are telling the truth?"}',75);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_8d701b916652','ch_e13b8f0edb1b','text','{"text": "GERRARD : Oh, don’t be a fool. Look for yourself. (Gerrard opens door and steps away. Intruder leans forward to inspect it, with his side towards Gerrard, but with the revolver ready. As he turns his head, Gerrard gives him a push into the cupboard, knocking the revolver out of his hand. He slams the door and locks it, picks up the revolver and goes to the phone, where he stands with the gun pointed at the cupboard door.)"}',76);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_db6656ae14ff','ch_e13b8f0edb1b','text','{"text": "INTRUDER : (rattles door and shouts) Let me out of here!"}',77);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_4c3b59bde18a','ch_e13b8f0edb1b','text','{"text": "GERRARD : Hello. Yes, speaking. Sorry I can’t let you have the props in time for rehearsal, I’ve had a spot of bother — quite amusing. I think I’ll put it in my next play. Listen, can you tell our friend the Sergeant to come up here at once? You’ll probably find him in the Public Bar."}',78);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_67baa434ba07','ch_e13b8f0edb1b','heading','{"level": 2, "text": "Douglas James"}',79);
INSERT INTO blocks (id,chapter_id,type,data,sort_order) VALUES ('blk_ccc9152a1271','ch_e13b8f0edb1b','text','{"text": "*********"}',80);
